/**
 * mysw-extensions.js —— 可选功能合并包
 * · 分节注释「====== 原文件名 ======」保持可回溯，内容未改动；
 * · 三个 defaultOff 的大体积脚本（forest-icefire / icefire-workshop /
 * learn-tutor）仍保留独立文件，维持「勾选后才下载」的省流量语义；
 * · script-loader.js 已适配：任一成员启用即加载本包。
 */


/* ====== chat-hooks.js ====== */
/**
 * chat-hooks.js —— 聊天生命周期挂钩中心（扩展模块的统一介入点）
 * 正则脚本 / 预设 / 翻译 / 数据银行 / 消息脚本等都要在「发消息 / 入库 / 组装请求 /
 * 渲染」时介入文本。若各模块自行包装 sendMessage 与 fetchChat，会互相嵌套、顺序
 */
(function () {
    'use strict';
    if (window.ScriptLoader && typeof ScriptLoader.isEnabled === 'function' && !ScriptLoader.isEnabled('chat-hooks.js')) return;

    var PHASES = ['slashCommand', 'userInput', 'aiOutput', 'worldbook', 'promptAssembly', 'display'];
    var handlers = { slashCommand: [], userInput: [], aiOutput: [], worldbook: [], promptAssembly: [], display: [] };

    /* ---------------- 注册 / 执行 ---------------- */

    function sortList(list) {
        list.sort(function (a, b) { return a.order - b.order; });
    }

    function register(phase, id, fn, order) {
        var list = handlers[phase];
        if (!list || typeof fn !== 'function') return false;
        var n = Number(order);
        var item = { id: String(id || ('h' + list.length)), fn: fn, order: isFinite(n) ? n : 100 };
        for (var i = 0; i < list.length; i++) {
            if (list[i].id === item.id) { list[i] = item; sortList(list); return true; }
        }
        list.push(item);
        sortList(list);
        return true;
    }

    function unregister(phase, id) {
        var list = handlers[phase];
        if (!list) return false;
        for (var i = 0; i < list.length; i++) {
            if (list[i].id === id) { list.splice(i, 1); return true; }
        }
        return false;
    }

    function hasAny(phase) {
        return !!(handlers[phase] && handlers[phase].length);
    }

    function meta(extra) {
        var user = '', char = '', fid = null, fr = null;
        try { user = String(window.myUserName != null ? window.myUserName : (localStorage.getItem('myUserName') || '')); } catch (e) {}
        try { fid = window.currentFriendId != null ? window.currentFriendId : null; } catch (e) {}
        try { if (window.friendsData && fid != null) fr = window.friendsData[fid]; } catch (e) {}
        if (!fr) { try { if (typeof getFriends === 'function') fr = getFriends()[fid]; } catch (e) {} }
        if (fr && fr.name) char = String(fr.name);
        var out = { user: user.replace(/^\s+|\s+$/g, ''), char: char, friendId: fid };
        if (extra) { for (var k in extra) { if (Object.prototype.hasOwnProperty.call(extra, k)) out[k] = extra[k]; } }
        return out;
    }

    function runText(phase, text, extra) {
        if (typeof text !== 'string' || !text) return text;
        var list = handlers[phase];
        if (!list || !list.length) return text;
        if (text.length > 400000) return text;
        var m = meta(extra);
        m.phase = phase;
        var cur = text;
        for (var i = 0; i < list.length; i++) {
            try {
                var out = list[i].fn(cur, m);
                if (typeof out === 'string') cur = out;
            } catch (e) {
                try { console.warn('[ChatHooks] ' + phase + '/' + list[i].id + ' 中间件出错：', e); } catch (e2) {}
            }
        }
        return cur;
    }

    function runMessages(messages, extra) {
        var list = handlers.promptAssembly;
        if (!Array.isArray(messages) || !list || !list.length) return messages;
        // 辅助请求（翻译等）会给自己打上标记：不叠加提示词预设 / 组装层正则，避免污染系统提示词
        if (messages.__skipHooks) return messages;
        var m = meta(extra);
        m.phase = 'promptAssembly';
        var jobs = [];
        for (var i = 0; i < list.length; i++) {
            try {
                var ret = list[i].fn(messages, m);
                // 异步中间件（如聊天向量记忆的语义检索）：返回 Promise 时先收集，
                // 由调用方（wrapFetchChat）等待完成后再真正发出请求。
                if (ret && typeof ret.then === 'function') {
                    jobs.push(ret.then(function () {}, function () {}));
                }
            } catch (e) {
                try { console.warn('[ChatHooks] promptAssembly/' + list[i].id + ' 中间件出错：', e); } catch (e2) {}
            }
        }
        return jobs.length ? Promise.all(jobs).then(function () { return messages; }) : messages;
    }

    /* ---------------- 显示阶段：聊天区文字节点替换 ---------------- */

    var SKIP_TAGS = { SCRIPT: 1, STYLE: 1, TEXTAREA: 1, INPUT: 1, CODE: 1, PRE: 1, A: 1, BUTTON: 1, KBD: 1, SAMP: 1, SELECT: 1, OPTION: 1 };
    var nodeState = new WeakMap();   // 文字节点 -> 我们写入的结果（用于跳过重复处理）
    var domTimer = 0;

    function processNode(node, m) {
        var parent = node.parentNode;
        if (!parent) return 0;
        if (SKIP_TAGS[parent.nodeName]) return 0;
        if (parent.closest && parent.closest('[data-no-hooks]')) return 0;
        var val = node.nodeValue;
        if (!val || !val.trim()) return 0;
        if (nodeState.get(node) === val) return 0;
        var out = runText('display', val, m);
        if (out !== val) { try { node.nodeValue = out; } catch (e) {} }
        nodeState.set(node, out);
        return out !== val ? 1 : 0;
    }

    function refreshDom(scope) {
        if (!hasAny('display')) return 0;
        var host = scope || document.getElementById('chat-messages');
        if (!host || !document.createTreeWalker) return 0;
        var walker = document.createTreeWalker(host, NodeFilter.SHOW_TEXT, null);
        var m = meta();
        m.phase = 'display';
        var changed = 0, guard = 0;
        while (walker.nextNode()) {
            guard += 1;
            if (guard > 4000) break;
            changed += processNode(walker.currentNode, m);
        }
        return changed;
    }

    function scheduleRefresh() {
        if (!hasAny('display') || domTimer) return;
        domTimer = setTimeout(function () { domTimer = 0; try { refreshDom(); } catch (e) {} }, 260);
    }

    function observeChat() {
        var host = document.getElementById('chat-messages');
        if (!host) return false;
        if (host.__chatHooksObserved) return true;
        host.__chatHooksObserved = true;
        var mo = new MutationObserver(function (records) {
            for (var i = 0; i < records.length; i++) {
                var t = records[i].type;
                if (t === 'childList' || t === 'characterData') { scheduleRefresh(); return; }
            }
        });
        mo.observe(host, { childList: true, subtree: true, characterData: true });
        scheduleRefresh();
        return true;
    }

    /* ---------------- 挂钩安装（轮询直到宿主函数就绪） ---------------- */

    function wrapSendMessage() {
        var orig = window.sendMessage;
        if (typeof orig !== 'function') return false;
        if (orig.__chatHooks) return true;
        var wrapped = function (content, type) {
            // 原生 sendMessage 的 type 参数有默认值（= 'text'），但默认值只在原函数内部生效：
            // 直接调用 sendMessage(text) 时，包装层收到的 type 是 undefined。必须把 undefined
            // 也视为 text，否则「用户输入 / 斜杠命令」两个位置对普通发消息完全不生效。
            if ((type === undefined || type === 'text') && typeof content === 'string' && content) {
                var args = Array.prototype.slice.call(arguments);
                var text = content;
                if (text.charAt(0) === '/' && hasAny('slashCommand')) {
                    text = runText('slashCommand', text, { source: 'slash' });
                }
                if (text.charAt(0) !== '/' && hasAny('userInput')) {
                    text = runText('userInput', text, { source: 'user' });
                }
                args[0] = text;
                return orig.apply(this, args);
            }
            return orig.apply(this, arguments);
        };
        wrapped.__chatHooks = true;
        window.sendMessage = wrapped;
        return true;
    }

    // addMessageToSpecificThread(friendId, threadId, role, content, type, isProactive, extra)
    function wrapAddMessageToSpecificThread() {
        var orig = window.addMessageToSpecificThread;
        if (typeof orig !== 'function') return false;
        if (orig.__chatHooks) return true;
        var wrapped = function (friendId, threadId, role, content, type) {
            if (role === 'other' && type === 'text' && typeof content === 'string' && content && hasAny('aiOutput')) {
                var args = Array.prototype.slice.call(arguments);
                args[3] = runText('aiOutput', content, { source: 'ai', friendId: friendId });
                return orig.apply(this, args);
            }
            return orig.apply(this, arguments);
        };
        wrapped.__chatHooks = true;
        window.addMessageToSpecificThread = wrapped;
        return true;
    }

    function wrapWorldBook() {
        var wb = window.WorldBook;
        if (!wb || typeof wb.buildContext !== 'function') return false;
        if (wb.buildContext.__chatHooks) return true;
        var orig = wb.buildContext;
        wb.buildContext = function () {
            var result = orig.apply(this, arguments);
            try {
                if (result && typeof result === 'object' && hasAny('worldbook')) {
                    if (typeof result.before === 'string' && result.before) result.before = runText('worldbook', result.before, { source: 'worldbook' });
                    if (typeof result.after === 'string' && result.after) result.after = runText('worldbook', result.after, { source: 'worldbook' });
                }
            } catch (e) {}
            return result;
        };
        wb.buildContext.__chatHooks = true;
        return true;
    }

    function wrapFetchChat() {
        var am = window.ApiModule;
        if (!am || typeof am.fetchChat !== 'function') return false;
        if (am.fetchChat.__chatHooks) return true;
        var orig = am.fetchChat;
        am.fetchChat = function (apiSettings, messages) {
            var self = this;
            var args = arguments;
            var pending = null;
            try { pending = runMessages(messages); } catch (e) { pending = null; }
            // 存在异步中间件（如向量记忆检索）时，等它完成再发出请求
            if (pending && typeof pending.then === 'function') {
                var go = function () { return orig.apply(self, args); };
                return pending.then(go, go);
            }
            return orig.apply(self, args);
        };
        am.fetchChat.__chatHooks = true;
        return true;
    }

    // 新消息很可能在挂钩安装前就出现了；按钮挂载交给 onReady 回调队列
    var readyCbs = [];

    function boot() {
        var tries = 0;
        (function attempt() {
            tries += 1;
            var ok = 0, total = 0;
            [wrapSendMessage, wrapAddMessageToSpecificThread, wrapWorldBook, wrapFetchChat].forEach(function (fn) {
                total += 1;
                try { if (fn()) ok += 1; } catch (e) {}
            });
            total += 1;
            try { if (observeChat()) ok += 1; } catch (e) {}
            if (ok >= total) {
                readyCbs.splice(0).forEach(function (cb) { try { cb(); } catch (e) {} });
                return;
            }
            if (tries < 60) setTimeout(attempt, 400);
        })();
    }

    function onReady(cb) {
        if (typeof cb !== 'function') return;
        var st = window.ChatHooks.status();
        var all = st.sendMessage && st.addMessageToSpecificThread && st.worldbook && st.fetchChat && st.displayHost;
        if (all) { try { cb(); } catch (e) {} return; }
        readyCbs.push(cb);
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
    else boot();

    window.ChatHooks = {
        PHASES: PHASES.slice(),
        register: register,
        unregister: unregister,
        hasAny: hasAny,
        runText: runText,
        runMessages: runMessages,
        refreshDom: refreshDom,
        meta: meta,
        onReady: onReady,
        status: function () {
            return {
                sendMessage: typeof window.sendMessage === 'function' && !!window.sendMessage.__chatHooks,
                addMessageToSpecificThread: typeof window.addMessageToSpecificThread === 'function' && !!window.addMessageToSpecificThread.__chatHooks,
                worldbook: !!(window.WorldBook && window.WorldBook.buildContext && window.WorldBook.buildContext.__chatHooks),
                fetchChat: !!(window.ApiModule && window.ApiModule.fetchChat && window.ApiModule.fetchChat.__chatHooks),
                displayHost: !!(document.getElementById('chat-messages') && document.getElementById('chat-messages').__chatHooksObserved)
            };
        }
    };
})();


/* ====== english-mode.js ====== */
/**
 * english-mode.js —— AI 英文模式
 * · 存储 localStorage['englishModeSettings']
 * { enabled, scopes: { chat, live, forum, tutor, call, games } }
 * · 各场景调用 EnglishMode.applyToSystem(text, scope) 幂等追加英文规则
 * （带 [English Mode] 标记防重复）；
 * · 聊天场景额外接入 chat-hooks.js 的 promptAssembly：请求发出前给最后
 * 一条 system 追加规则，单聊 / 群聊 / 重新生成全覆盖；
 * · 设置面板挂在「设置 → 更多 → 界面语言」区块下方。
 * 安全边界：
 * · 内部辅助请求（表情包备注 / 情绪判断 / 知识库问答 / 翻译）不注入；
 * · 总开关关闭时 applyToSystem 原样返回，行为与旧版一致；
 * · ChatHooks 未加载时静默等待重试，不影响其它功能。
 */
(function () {
    'use strict';
    if (window.ScriptLoader && typeof ScriptLoader.isEnabled === 'function' && !ScriptLoader.isEnabled('english-mode.js')) return;

    var KEY = 'englishModeSettings';
    var MARK = '[English Mode]';
    var SCOPE_KEYS = ['chat', 'live', 'forum', 'tutor', 'call', 'games'];
    var DEFAULT_SCOPES = { chat: true, live: true, forum: true, tutor: true, call: true, games: true };

    /* ---------------- 设置读写 ---------------- */

    function readSettings() {
        var out = { enabled: false, scopes: {} };
        SCOPE_KEYS.forEach(function (k) { out.scopes[k] = DEFAULT_SCOPES[k]; });
        try {
            var raw = JSON.parse(localStorage.getItem(KEY) || 'null');
            if (raw && typeof raw === 'object') {
                out.enabled = raw.enabled === true;
                if (raw.scopes && typeof raw.scopes === 'object') {
                    SCOPE_KEYS.forEach(function (k) {
                        if (raw.scopes[k] === false) out.scopes[k] = false;
                        else if (raw.scopes[k] === true) out.scopes[k] = true;
                    });
                }
            }
        } catch (e) { /* 坏数据按默认处理 */ }
        return out;
    }

    function writeSettings(next) {
        try { localStorage.setItem(KEY, JSON.stringify(next)); } catch (e) { /* 配额不足忽略 */ }
    }

    function isEnabled() { return readSettings().enabled === true; }

    /** 总开关开启 且 该场景未被单独关掉 */
    function isScope(scope) {
        var s = readSettings();
        if (!s.enabled) return false;
        if (!scope || SCOPE_KEYS.indexOf(scope) === -1) return true;
        return s.scopes[scope] !== false;
    }

    function setEnabled(v) {
        var s = readSettings();
        s.enabled = v === true;
        writeSettings(s);
        return s;
    }

    function setScope(scope, v) {
        var s = readSettings();
        if (SCOPE_KEYS.indexOf(scope) !== -1) s.scopes[scope] = v === true;
        writeSettings(s);
        return s;
    }

    /* ---------------- 语言规则（各场景的英文指令块） ----------------
       统一带 [English Mode] 前缀，供幂等检测；
       声明最高优先级，覆盖角色卡 / 预设里要求中文的旧指令；
       标记类内容（[sticker:N]、[AFF:n]、【第N步】等）要求原样保留。 */

    var BLOCKS = {
        chat: [
            MARK + ' Language policy (highest priority; it overrides any earlier instruction that asks you to reply in Chinese):',
            '- Always reply in natural, idiomatic English, regardless of the language of the character card, the chat history or the user message.',
            '- Keep the persona, tone and world-view of the character; express everything in English.',
            '- Keep required markers and placeholders byte-for-byte unchanged ([sticker:N], [AFF:n], [emo:xxx]); only natural-language text switches to English.',
            '- Do not mention this rule; simply comply.'
        ].join('\n'),

        live: [
            MARK + ' Language policy (highest priority; overrides any earlier request for Chinese):',
            '- Output the requested line in English only: one short, natural English sentence.',
            '- Keep the persona and tone of the character; do not mention this rule.'
        ].join('\n'),

        forum: [
            MARK + ' Language policy (highest priority; overrides any earlier instruction that asks for Chinese only):',
            '- Write it in natural, colloquial English, in the voice of the character, like a real forum user.',
            '- Keep it casual; do not mention this rule.'
        ].join('\n'),

        tutor: [
            MARK + ' Language policy (highest priority; overrides any instruction that asks for Chinese output):',
            '- Explain and answer in English only, regardless of the language of the question or earlier instructions.',
            '- Keep fixed format markers byte-for-byte unchanged (【第N步】, 【答案】, 【知识点】, 【题型套路】, 【易错点】, 「练习1」); write the text after them in English; never rename or remove the markers.',
            '- Keep KaTeX formulas working; write Mermaid node labels in English.',
            '- In a voice call, speak natural spoken English, one point per turn. Do not mention this rule.'
        ].join('\n'),

        call: [
            MARK + ' Language policy (highest priority; overrides any earlier request for Chinese):',
            '- Speak English only during this call: short, casual, spoken sentences, like a real phone call.',
            '- Use no Chinese words or sentences. Do not mention this rule.'
        ].join('\n'),

        games: [
            MARK + ' Language policy (highest priority; overrides any earlier request for Chinese):',
            '- Say it in English only: one short, natural English line in the voice of the character.',
            '- Keep any required JSON structure and coordinates unchanged; only human-readable text becomes English. Do not mention this rule.'
        ].join('\n')
    };

    /** 该场景当前生效的规则块；未开启返回空串 */
    function promptBlock(scope) {
        if (!isScope(scope)) return '';
        return BLOCKS[scope] || BLOCKS.chat;
    }

    /** 幂等追加：已含标记或未开启时原样返回 */
    function applyToSystem(text, scope) {
        var block = promptBlock(scope);
        var s = String(text == null ? '' : text);
        if (!block) return s;
        if (s.indexOf(MARK) !== -1) return s;
        return s ? (s + '\n\n' + block) : block;
    }
    /* ---------------- 聊天场景：接入 chat-hooks.js ----------------
       与数据银行 / 提示词预设同机制：promptAssembly 阶段在请求发出前直接改
       messages 数组。单聊、群聊、重新生成都走 ApiModule.fetchChat，一次接入
       即可全覆盖；带 __skipHooks 的辅助请求由 chat-hooks.js 统一跳过。 */

    var hookConnected = false;

    /** 内部辅助请求：不该被语言规则污染（走 fetchChat 的小任务） */
    function isInternalRequest(messages) {
        for (var i = 0; i < messages.length; i++) {
            var m = messages[i];
            if (!m || m.role !== 'system' || typeof m.content !== 'string') continue;
            var c = m.content;
            if (c.indexOf('图像描述助手') !== -1) return true;            // 表情包自动备注
            if (c.indexOf('判断 AI 回复应表现的情绪') !== -1) return true; // 3D 实验室情绪判断
            if (c.indexOf('知识库问答助手') !== -1) return true;           // 知识库问答
            if (/^\s*你是一名专业翻译/.test(c)) return true;              // 翻译类兜底
        }
        return false;
    }

    function applyToMessages(messages) {
        if (!isScope('chat')) return;
        if (!Array.isArray(messages) || !messages.length) return;
        if (isInternalRequest(messages)) return;
        // 追加到最后一条 system 上（不新增 system 消息：部分端点要求 system 只在首位出现）
        for (var i = messages.length - 1; i >= 0; i--) {
            var m = messages[i];
            if (!m || m.role !== 'system' || typeof m.content !== 'string') continue;
            if (m.content.indexOf(MARK) !== -1) return;
            m.content = m.content + '\n\n' + BLOCKS.chat;
            return;
        }
    }

    function connect() {
        if (hookConnected) return true;
        if (!window.ChatHooks || typeof window.ChatHooks.register !== 'function') return false;
        window.ChatHooks.register('promptAssembly', 'english-mode', function (messages) {
            try { applyToMessages(messages); } catch (e) { /* 单次注入失败不影响请求 */ }
        }, 70);
        hookConnected = true;
        return true;
    }

    if (!connect()) {
        var connTries = 0;
        var connTimer = setInterval(function () {
            if (connect() || ++connTries > 40) clearInterval(connTimer);
        }, 300);
    }

    /* ---------------- 设置面板（设置 → 更多 → 界面语言 下方） ---------------- */

    var panelEl = null;

    var UI_PHRASES = {
        'AI 英文模式': 'AI English mode',
        '开启后，让 AI 在勾选的场景里只说英文（界面文字不变）。与「角色卡翻译」配合：在 English 界面下把角色卡翻成英文后，可一键用它替换角色提示词。': 'When on, the AI speaks English only in the ticked scopes (interface text stays as-is). Pairs with card translation: under the English interface, translate a character card and replace its prompt with one click.',
        '让 AI 讲英文（总开关）': 'Make the AI speak English (master switch)',
        '正常聊天（含群聊、问候、主动关怀）': 'Chat (incl. group chat, greetings, proactive care)',
        'AI 直播间（台词 / 弹幕 / 礼物反应）': 'AI live room (lines / danmaku / gift reactions)',
        '论坛（发帖 / 评论 / 私信）': 'Forum (posts / comments / DMs)',
        '学习辅导（讲解 / 追问 / 辅导通话）': 'Study tutor (explanations / follow-ups / tutor call)',
        '语音 / 视频通话（实验室）': 'Voice / video call (Laboratory)',
        '小游戏（棋局闲聊、森林冰火人）': 'Mini-games (board chat, Forest Icefire)',
        '当前：已关闭': 'Now: off',
        '当前：已开启（勾选场景生效）': 'Now: on (for the ticked scopes)'
    };

    function registerI18n() {
        try {
            if (window.SiteI18n && typeof window.SiteI18n.addPhrases === 'function') {
                window.SiteI18n.addPhrases(UI_PHRASES);
            }
        } catch (e) { /* 无 i18n 时保持中文 */ }
    }

    /* 状态文案始终写中文：英文界面由 SiteI18n 短语表（见 UI_PHRASES）自动替换，
       中英来回切换时也能正确还原，不在这里直接写英文。 */
    function statusText(s) {
        return s.enabled ? '当前：已开启（勾选场景生效）' : '当前：已关闭';
    }

    function scopeRow(key, label) {
        return '<label style="display:flex;align-items:center;gap:8px;"><input type="checkbox" data-em-scope="' + key + '"> <span>' + label + '</span></label>';
    }

    function mountPanel() {
        if (panelEl) return true;
        var anchor = document.getElementById('more-language');
        if (!anchor || !anchor.parentNode) return false;
        panelEl = document.createElement('div');
        panelEl.className = 'form-group';
        panelEl.id = 'english-mode-box';
        panelEl.style.cssText = 'border-bottom: 1px dashed #444; padding-bottom: 15px; margin-bottom: 15px;';
        panelEl.innerHTML = [
            '<h4><i class="ri-global-line"></i> AI 英文模式</h4>',
            '<p style="font-size: 0.85em; color: #aaa; margin-bottom: 10px;">开启后，让 AI 在勾选的场景里只说英文（界面文字不变）。与「角色卡翻译」配合：在 English 界面下把角色卡翻成英文后，可一键用它替换角色提示词。</p>',
            '<label style="display:flex;align-items:center;gap:8px;margin-bottom:10px;font-weight:600;"><input type="checkbox" id="em-enabled"> <span>让 AI 讲英文（总开关）</span></label>',
            '<div id="em-scopes" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px;font-size:0.88em;color:#cfd3dd;">',
            scopeRow('chat', '正常聊天（含群聊、问候、主动关怀）'),
            scopeRow('live', 'AI 直播间（台词 / 弹幕 / 礼物反应）'),
            scopeRow('forum', '论坛（发帖 / 评论 / 私信）'),
            scopeRow('tutor', '学习辅导（讲解 / 追问 / 辅导通话）'),
            scopeRow('call', '语音 / 视频通话（实验室）'),
            scopeRow('games', '小游戏（棋局闲聊、森林冰火人）'),
            '</div>',
            '<p id="em-status" style="font-size: 0.8em; color: #8d93a2; margin-top: 10px;"></p>'
        ].join('');
        anchor.parentNode.insertBefore(panelEl, anchor.nextSibling);

        var enabledBox = panelEl.querySelector('#em-enabled');
        var statusEl = panelEl.querySelector('#em-status');
        var scopeBoxes = Array.prototype.slice.call(panelEl.querySelectorAll('[data-em-scope]'));

        function paint() {
            var s = readSettings();
            enabledBox.checked = s.enabled;
            scopeBoxes.forEach(function (box) {
                box.checked = s.scopes[box.getAttribute('data-em-scope')] !== false;
                box.disabled = !s.enabled;
            });
            panelEl.querySelector('#em-scopes').style.opacity = s.enabled ? '1' : '0.55';
            statusEl.textContent = statusText(s);
        }

        enabledBox.addEventListener('change', function () {
            setEnabled(enabledBox.checked);
            paint();
        });
        scopeBoxes.forEach(function (box) {
            box.addEventListener('change', function () {
                setScope(box.getAttribute('data-em-scope'), box.checked);
                paint();
            });
        });
        paint();
        return true;
    }

    function boot() {
        registerI18n();
        var tries = 0;
        (function attempt() {
            tries += 1;
            try { if (mountPanel()) return; } catch (e) { /* 挂载失败不阻断其它功能 */ }
            if (tries < 40) setTimeout(attempt, 400);
        })();
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
    else boot();

    window.EnglishMode = {
        KEY: KEY,
        MARK: MARK,
        SCOPE_KEYS: SCOPE_KEYS,
        isEnabled: isEnabled,
        isScope: isScope,
        promptBlock: promptBlock,
        applyToSystem: applyToSystem,
        applyToMessages: applyToMessages,
        settings: readSettings,
        setEnabled: setEnabled,
        setScope: setScope,
        mountPanel: mountPanel
    };
})();


/* ====== regex-scripts.js ====== */
/**
 * regex-scripts.js —— 正则脚本（Regex Scripts）
 * userInput      用户输入：消息发出前替换（输入框里的原文不变）
 * slashCommand   斜杠命令：以 / 开头的输入按此位置处理
 * aiOutput       AI 输出：回复写入聊天记录前替换（持久生效）
 * worldbook      世界书：世界书注入提示词前替换
 * promptAssembly 提示词组装：请求发给模型前对全部消息文本替换
 * display        聊天显示：渲染到气泡时替换（不改聊天记录）
 * 替换串宏：
 * {{match}} 整个匹配      $1 .. $9  第 n 个捕获组
 * {{user}}  用户名        {{char}}  当前角色名
 */
(function () {
    'use strict';
    if (window.ScriptLoader && typeof ScriptLoader.isEnabled === 'function' && !ScriptLoader.isEnabled('regex-scripts.js')) return;

    var KEY = 'regexScripts';
    var MAX_TEXT = 400000;       // 单段文本超过此长度直接跳过，防止极端卡顿
    var MAX_SCRIPTS_PER_APPLY = 60;

    var PLACEMENTS = [
        { id: 'userInput', label: '用户输入', hint: '你发出的消息进入对话前替换；输入框里的原文不会变化。' },
        { id: 'slashCommand', label: '斜杠命令', hint: '以 / 开头的输入按此位置处理（例如把 /roll 展开成规则文本）。' },
        { id: 'aiOutput', label: 'AI 输出', hint: 'AI 回复写入聊天记录前替换，持久生效：导出、重绘、后续上下文都使用处理后的文本。' },
        { id: 'worldbook', label: '世界书', hint: '世界书内容注入提示词之前替换。' },
        { id: 'promptAssembly', label: '提示词组装', hint: '请求正式发给模型前，对全部消息文本替换。' },
        { id: 'display', label: '聊天显示', hint: '渲染到气泡时替换文本（不动聊天记录，也不影响导出与上下文）。' }
    ];
    var PLACEMENT_IDS = [];
    PLACEMENTS.forEach(function (p) { PLACEMENT_IDS.push(p.id); });

    /* ---------------- 通用工具 ---------------- */

    function esc(s) {
        return String(s == null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
    }

    function toast(msg, icon) {
        try { if (typeof window.showToast === 'function') window.showToast(msg, icon || 'ri-information-line'); }
        catch (e) {}
    }

    function readJson(key, fallback) {
        try {
            var raw = localStorage.getItem(key);
            if (!raw) return fallback;
            var parsed = JSON.parse(raw);
            return parsed == null ? fallback : parsed;
        } catch (e) { return fallback; }
    }

    function writeJson(key, value) {
        try {
            if (typeof setLocalStorageSafely === 'function') return setLocalStorageSafely(key, JSON.stringify(value), '正则脚本') !== false;
            localStorage.setItem(key, JSON.stringify(value));
            return true;
        } catch (e) {
            toast('保存失败：浏览器存储不可用', 'ri-error-warning-line');
            return false;
        }
    }

    /* ---------------- 数据层 ---------------- */

    var uidSeq = 0;
    function newId() {
        uidSeq += 1;
        return 'rx_' + Date.now().toString(36) + '_' + uidSeq;
    }

    function normalizeScript(raw) {
        var s = raw && typeof raw === 'object' ? raw : {};
        var placement = {};
        var any = false;
        PLACEMENT_IDS.forEach(function (id) {
            placement[id] = !!(s.placement && s.placement[id]);
            if (placement[id]) any = true;
        });
        // 旧数据 / 新建数据位置全空时，默认落到「AI 输出 + 聊天显示」，避免看起来没生效
        if (!any) { placement.aiOutput = true; placement.display = true; }
        return {
            id: String(s.id || '') || newId(),
            name: String(s.name || '未命名脚本'),
            enabled: s.enabled !== false,
            findRegex: String(s.findRegex || ''),
            replaceString: String(s.replaceString || ''),
            flags: String(s.flags || 'gi'),
            placement: placement,
            order: Number.isFinite(Number(s.order)) ? Number(s.order) : 100
        };
    }

    function loadScripts() {
        var raw = readJson(KEY, []);
        var list = Array.isArray(raw) ? raw : (raw && Array.isArray(raw.scripts) ? raw.scripts : []);
        return list.map(normalizeScript).sort(function (a, b) {
            return (a.order - b.order) || String(a.id).localeCompare(String(b.id));
        });
    }

    function saveScripts(list) {
        return writeJson(KEY, { version: 1, scripts: (list || []).map(normalizeScript) });
    }

    function enabledScripts(placement) {
        return loadScripts().filter(function (s) {
            return s.enabled && s.placement[placement] && s.findRegex;
        });
    }

    function currentCtx() {
        var user = '', char = '';
        try { user = String(localStorage.getItem('myUserName') || '').trim(); } catch (e) {}
        try { if (window.myUserName) user = String(window.myUserName); } catch (e) {}
        try {
            var fid = window.currentFriendId;
            var data = window.friendsData;
            if (!data && typeof window.getFriends === 'function') data = window.getFriends();
            if (fid && data && data[fid] && data[fid].name) char = String(data[fid].name);
        } catch (e) {}
        if (!char) {
            try {
                var el = document.querySelector('.friend-item.active .friend-name, .friend-item.active .name');
                if (el) char = String(el.textContent || '').trim();
            } catch (e) {}
        }
        return { user: user, char: char };
    }

    /* ---------------- 引擎 ---------------- */

    var compileCache = new Map();

    function compile(script) {
        var src = String(script.findRegex || '');
        var flags = String(script.flags || '');
        var sig = src + '\u0000' + flags;
        if (compileCache.has(sig)) return compileCache.get(sig);
        // 支持 /pattern/flags 写法
        if (src.charAt(0) === '/' && src.lastIndexOf('/') > 0) {
            var end = src.lastIndexOf('/');
            var tail = src.slice(end + 1);
            if (/^[gimsuy]*$/.test(tail)) {
                if (tail) flags = tail;
                src = src.slice(1, end);
            }
        }
        var re = null;
        try { re = new RegExp(src, flags); } catch (e) { re = null; }
        if (compileCache.size > 300) compileCache.clear();
        compileCache.set(sig, re);
        return re;
    }

    function expandReplacement(tpl, caps, ctx) {
        var out = String(tpl == null ? '' : tpl);
        out = out.split('$0').join(caps[0] || '');
        out = out.split('{{match}}').join(caps[0] || '');
        out = out.replace(/\$([1-9])/g, function (all, d) {
            var v = caps[parseInt(d, 10)];
            return v == null ? '' : v;
        });
        out = out.replace(/\{\{(user|char|date|time)\}\}/g, function (all, k) {
            if (k === 'user') return (ctx && ctx.user) || '用户';
            if (k === 'char') return (ctx && ctx.char) || '角色';
            if (k === 'date') return new Date().toLocaleDateString('zh-CN');
            return new Date().toLocaleTimeString('zh-CN');
        });
        return out;
    }

    function applyOne(text, script, ctx) {
        if (typeof text !== 'string' || !text || text.length > MAX_TEXT) return { text: text, changed: false };
        var re = compile(script);
        if (!re) return { text: text, changed: false };
        re.lastIndex = 0;
        var changed = false;
        var out = text.replace(re, function () {
            var args = Array.prototype.slice.call(arguments);
            var caps = args.slice();
            if (typeof caps[caps.length - 1] === 'object') caps.pop();  // groups
            caps.pop();  // string
            caps.pop();  // offset
            changed = true;
            return expandReplacement(script.replaceString, caps, ctx);
        });
        return { text: out, changed: changed };
    }

    function applyPlacement(text, placement, ctx) {
        if (typeof text !== 'string' || !text) return text;
        var list = enabledScripts(placement);
        if (!list.length) return text;
        var out = text;
        var n = Math.min(list.length, MAX_SCRIPTS_PER_APPLY);
        for (var i = 0; i < n; i++) {
            out = applyOne(out, list[i], ctx).text;
        }
        return out;
    }

    // 对 messages 数组（OpenAI 格式）做提示词组装替换：content 可能是字符串或 parts 数组
    // 辅助视觉请求（表情包自动备注）的识别：内部小任务，不是角色对话。
    // 与「提示词预设 / 数据银行 / 聊天向量记忆」的处理保持一致，避免用户规则改写内部请求。
    function isVisionHelperRequest(messages) {
        return Array.isArray(messages) && messages.length === 2
            && messages[0] && messages[0].role === 'system' && typeof messages[0].content === 'string'
            && /图像描述助手/.test(messages[0].content)
            && messages[1] && messages[1].role === 'user' && Array.isArray(messages[1].content)
            && messages[1].content.some(function (p) { return p && p.type === 'image_url'; });
    }

    function applyToMessages(messages, ctx) {
        if (!Array.isArray(messages)) return messages;
        if (!enabledScripts('promptAssembly').length) return messages;
        if (isVisionHelperRequest(messages)) return messages;
        messages.forEach(function (m) {
            if (!m || typeof m !== 'object') return;
            if (typeof m.content === 'string') {
                m.content = applyPlacement(m.content, 'promptAssembly', ctx);
            } else if (Array.isArray(m.content)) {
                m.content.forEach(function (part) {
                    if (part && typeof part === 'object' && typeof part.text === 'string') {
                        part.text = applyPlacement(part.text, 'promptAssembly', ctx);
                    }
                });
            }
        });
        return messages;
    }

    window.RegexScripts = {
        PLACEMENTS: PLACEMENTS,
        list: loadScripts,
        save: saveScripts,
        enabled: enabledScripts,
        applyPlacement: applyPlacement,
        applyToMessages: applyToMessages,
        applyOne: applyOne,
        currentCtx: currentCtx
    };
})();

/* ============================================================
   第二部分：接入 ChatHooks（聊天生命周期挂钩中心）
   六个执行位置与 ChatHooks 的六个阶段同名，一一注册。
   ChatHooks 未就绪时轮询等待（最长 20 秒）；失败只影响对应位置。
 */
(function () {
    'use strict';
    var RS = window.RegexScripts;
    if (!RS) return;

    function connect() {
        if (!window.ChatHooks || typeof window.ChatHooks.register !== 'function') return false;
        var CH = window.ChatHooks;
        ['slashCommand', 'userInput', 'aiOutput', 'worldbook', 'display'].forEach(function (phase) {
            CH.register(phase, 'regex-scripts', function (text, meta) {
                try { return RS.applyPlacement(text, phase, meta); }
                catch (e) { return text; }
            }, 30);
        });
        CH.register('promptAssembly', 'regex-scripts', function (messages, meta) {
            try { RS.applyToMessages(messages, meta); } catch (e) {}
        }, 30);
        return true;
    }

    if (!connect()) {
        var tries = 0;
        var timer = setInterval(function () {
            tries += 1;
            if (connect() || tries > 80) clearInterval(timer);
        }, 250);
    }
})();

/* ============================================================
   第三部分：管理面板（设置 → 插件 → 正则脚本）
   列表（启用 / 位置 / 顺序 / 编辑 / 删除）+ 编辑区 +
   单条试运行 + 导入导出 JSON + 挂钩状态显示。
 */
(function () {
    'use strict';
    var overlay = null;
    var editingId = '';

    function esc(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, function (ch) {
            return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch];
        });
    }

    function toast(msg, icon) {
        try { if (typeof window.showToast === 'function') window.showToast(msg, icon || 'ri-information-line'); }
        catch (e) {}
    }

    function api() { return window.RegexScripts; }
    function rows() { return (api() && api().list()) || []; }

    function injectStyle() {
        if (document.getElementById('regex-panel-style')) return;
        var st = document.createElement('style');
        st.id = 'regex-panel-style';
        st.textContent = [
            '.rxs-tip{font-size:.82em;color:#8d93a1;line-height:1.7;margin:0 0 10px}',
            '.rxs-hooks{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}',
            '.rxs-hook{font-size:.72em;padding:2px 8px;border-radius:999px;border:1px solid #4a4e5c;color:#9aa0ad}',
            '.rxs-hook.ok{border-color:rgba(120,220,150,.5);color:#8fe0a8}',
            '.rxs-hook.bad{border-color:rgba(255,110,110,.5);color:#ff9a9a}',
            '.rxs-editor{display:flex;flex-direction:column;gap:8px;padding:12px;border:1px solid #3b3f4b;border-radius:10px;background:rgba(255,255,255,.03);margin-bottom:14px}',
            '.rxs-editor input,.rxs-editor textarea{width:100%;box-sizing:border-box;padding:8px;background:#20232c;border:1px solid #4a4e5c;border-radius:7px;color:#eee;font:inherit;font-size:.85em}',
            '.rxs-editor textarea{min-height:60px;resize:vertical;font-family:ui-monospace,Menlo,Consolas,monospace}',
            '.rxs-line{display:flex;gap:8px}',
            '.rxs-pls{display:flex;flex-wrap:wrap;gap:8px 14px}',
            '.rxs-chk{font-size:.8em;color:#cfd3dd;display:flex;align-items:center;gap:5px;cursor:pointer}',
            '.rxs-acts{display:flex;gap:8px;flex-wrap:wrap}',
            '.rxs-lab-out{white-space:pre-wrap;word-break:break-all;font-size:.8em;background:#1b1d26;border:1px dashed #4a4e5c;border-radius:8px;padding:8px;margin:0;max-height:150px;overflow:auto;color:#cfd3dd}',
            '.rxs-row{display:flex;align-items:center;gap:8px;padding:9px 10px;border:1px solid #3b3f4b;border-radius:10px;margin-bottom:8px;background:rgba(255,255,255,.03)}',
            '.rxs-main{flex:1 1 auto;min-width:0}',
            '.rxs-name{font-size:.9em;color:#e6c78a;word-break:break-all}',
            '.rxs-order{color:#7f8593;font-size:.78em;margin-left:6px}',
            '.rxs-tags{display:flex;gap:4px;flex-wrap:wrap;margin:3px 0}',
            '.rxs-tag{font-size:.68em;padding:1px 7px;border-radius:999px;border:1px solid rgba(255,255,255,.18);color:#b6bbc8}',
            '.rxs-tag.off{border-color:rgba(255,110,110,.4);color:#ff9a9a}',
            '.rxs-code{font-size:.72em;color:#8d93a1;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',
            '.rxs-empty{color:#8d93a1;font-size:.85em;text-align:center;padding:18px 0}'
        ].join('');
        document.head.appendChild(st);
    }

    function tagsOf(s) {
        var out = [];
        ((api() && api().PLACEMENTS) || []).forEach(function (p) {
            if (s.placement && s.placement[p.id]) out.push('<span class="rxs-tag">' + esc(p.label) + '</span>');
        });
        return out.join('') || '<span class="rxs-tag off">未指定位置</span>';
    }

    function renderHooks() {
        var el = overlay && overlay.querySelector('#rxs-hooks');
        if (!el) return;
        var st = window.ChatHooks && window.ChatHooks.status ? window.ChatHooks.status() : null;
        if (!st) { el.textContent = '挂钩中心（chat-hooks.js）未加载：脚本不会自动生效。'; return; }
        var names = { sendMessage: '用户输入', addMessageToSpecificThread: 'AI 输出', worldbook: '世界书', fetchChat: '提示词组装', displayHost: '聊天显示' };
        el.innerHTML = Object.keys(names).map(function (k) {
            var ok = !!st[k];
            return '<span class="rxs-hook ' + (ok ? 'ok' : 'bad') + '">' + names[k] + (ok ? ' ✓' : ' ✗') + '</span>';
        }).join('');
    }

    function renderList() {
        var host = overlay && overlay.querySelector('#rxs-list');
        if (!host) return;
        var list = rows();
        if (!list.length) {
            host.innerHTML = '<p class="rxs-empty">还没有正则脚本。填好上面的表单点「保存脚本」即可创建第一条；也可以用「导入」整包搬运。</p>';
            renderHooks();
            return;
        }
        host.innerHTML = list.map(function (s) {
            return '<div class="rxs-row" data-id="' + esc(s.id) + '">' +
                '<input type="checkbox" data-act="toggle"' + (s.enabled ? ' checked' : '') + ' title="启用 / 停用">' +
                '<div class="rxs-main">' +
                '<div class="rxs-name">' + esc(s.name) + '<span class="rxs-order">#' + Number(s.order) + '</span></div>' +
                '<div class="rxs-tags">' + tagsOf(s) + '</div>' +
                '<code class="rxs-code">' + esc(String(s.findRegex).slice(0, 140)) + '</code>' +
                '</div>' +
                '<button class="btn btn-outline btn-sm" data-act="edit">编辑</button>' +
                '<button class="btn btn-outline btn-sm" data-act="up" title="上移">↑</button>' +
                '<button class="btn btn-outline btn-sm" data-act="down" title="下移">↓</button>' +
                '<button class="btn btn-danger btn-sm" data-act="del">删</button>' +
                '</div>';
        }).join('');
        renderHooks();
    }

    /* ---------------- 编辑器：表单读写与增删改 ---------------- */

    function q(id) { return overlay ? overlay.querySelector('#' + id) : null; }

    function renderPlaceChecks() {
        var el = q('rxs-places');
        if (!el) return;
        var list = (api() && api().PLACEMENTS) || [];
        el.innerHTML = list.map(function (p) {
            return '<label class="rxs-chk" title="' + esc(p.hint) + '">' +
                '<input type="checkbox" data-place="' + esc(p.id) + '"> ' + esc(p.label) + '</label>';
        }).join('');
    }

    function fillForm(s) {
        editingId = (s && s.id) || '';
        if (q('rxs-name')) q('rxs-name').value = (s && s.name) || '';
        if (q('rxs-find')) q('rxs-find').value = (s && s.findRegex) || '';
        if (q('rxs-replace')) q('rxs-replace').value = (s && s.replaceString) || '';
        if (q('rxs-flags')) q('rxs-flags').value = (s && s.flags) || 'gi';
        if (q('rxs-order')) q('rxs-order').value = String((s && s.order) || 100);
        var boxes = overlay ? overlay.querySelectorAll('[data-place]') : [];
        for (var i = 0; i < boxes.length; i++) {
            var id = boxes[i].getAttribute('data-place');
            boxes[i].checked = !!(s && s.placement && s.placement[id]);
        }
        if (q('rxs-save')) q('rxs-save').innerHTML = s ? '<i class="ri-save-line"></i> 保存修改' : '<i class="ri-add-line"></i> 保存脚本';
        if (q('rxs-lab-out')) q('rxs-lab-out').hidden = true;
    }

    function readForm() {
        var placement = {};
        var any = false;
        var boxes = overlay ? overlay.querySelectorAll('[data-place]') : [];
        for (var i = 0; i < boxes.length; i++) {
            var id = boxes[i].getAttribute('data-place');
            placement[id] = !!boxes[i].checked;
            if (placement[id]) any = true;
        }
        if (!any) { placement.aiOutput = true; placement.display = true; }
        return {
            id: editingId || '',
            name: String(q('rxs-name') ? q('rxs-name').value : '').trim() || '未命名脚本',
            findRegex: String(q('rxs-find') ? q('rxs-find').value : '').trim(),
            replaceString: String(q('rxs-replace') ? q('rxs-replace').value : ''),
            flags: String(q('rxs-flags') ? q('rxs-flags').value : '').trim(),
            order: Number(q('rxs-order') ? q('rxs-order').value : 100) || 100,
            enabled: true,
            placement: placement
        };
    }

    function saveFromForm() {
        var item = readForm();
        if (!item.findRegex) { toast('请先填写查找正则', 'ri-error-warning-line'); return; }
        var probeSrc = item.findRegex;
        if (probeSrc.charAt(0) === '/' && probeSrc.lastIndexOf('/') > 0) probeSrc = '.*';
        try { new RegExp(probeSrc, item.flags || 'gi'); }
        catch (e) { toast('正则语法错误：' + e.message, 'ri-error-warning-line'); return; }

        var list = rows().slice();
        var idx = -1;
        for (var i = 0; i < list.length; i++) { if (list[i].id === item.id) { idx = i; break; } }
        if (idx >= 0) {
            item.enabled = list[idx].enabled;
            item.id = list[idx].id;
            list[idx] = item;
            toast('已保存修改：' + item.name, 'ri-check-line');
        } else {
            item.id = '';
            list.push(item);
            toast('已创建脚本：' + item.name, 'ri-check-line');
        }
        if (api().save(list)) { refreshPanel(); fillForm(null); }
    }

    function deleteById(id) {
        var target = null;
        var list = rows().filter(function (s) { if (s.id === id) { target = s; return false; } return true; });
        if (!target) return;
        var go = function () {
            api().save(list);
            if (editingId === id) fillForm(null);
            refreshPanel();
            toast('已删除脚本：' + target.name, 'ri-delete-bin-line');
        };
        if (window.Dlg && Dlg.confirm) {
            Dlg.confirm({ title: '删除脚本', message: '删除「' + target.name + '」？此操作不可撤销。', okText: '删除' }).then(function (yes) { if (yes) go(); });
        } else if (window.confirm('删除「' + target.name + '」？')) { go(); }
    }

    function moveById(id, dir) {
        var list = rows();
        var idx = -1;
        for (var i = 0; i < list.length; i++) { if (list[i].id === id) { idx = i; break; } }
        if (idx < 0) return;
        var j = idx + dir;
        if (j < 0 || j >= list.length) return;
        var tmp = list[idx]; list[idx] = list[j]; list[j] = tmp;
        for (var k = 0; k < list.length; k++) list[k].order = (k + 1) * 10;
        if (api().save(list)) refreshPanel();
    }

    function toggleById(id, enabled) {
        var list = rows();
        for (var i = 0; i < list.length; i++) { if (list[i].id === id) { list[i].enabled = !!enabled; break; } }
        api().save(list);
    }

    function testRun() {
        var item = readForm();
        if (!item.findRegex) { toast('请先填写查找正则', 'ri-error-warning-line'); return; }
        var inEl = q('rxs-lab-in');
        var input = String(inEl && inEl.value || '') || '你好，[emo:happy] 世界！这是发给我家 {{char}} 的测试文本。';
        var res;
        try { res = api().applyOne(input, item, { user: '测试用户', char: '测试角色' }); }
        catch (e) { toast('执行出错：' + e.message, 'ri-error-warning-line'); return; }
        var out = q('rxs-lab-out');
        if (out) {
            out.hidden = false;
            out.textContent = '输入：' + input + '\n输出：' + res.text + '\n' + (res.changed ? '（已发生替换）' : '（没有匹配，输出与输入相同）');
        }
    }

    function exportAll() {
        var list = rows();
        if (!list.length) { toast('还没有可导出的脚本', 'ri-error-warning-line'); return; }
        try {
            var payload = { app: 'MySW', kind: 'regexScripts', version: 1, exportedAt: Date.now(), scripts: list };
            var blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
            var url = URL.createObjectURL(blob);
            var a = document.createElement('a');
            a.href = url;
            a.download = 'mysw-regex-scripts-' + Date.now() + '.json';
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(function () { try { URL.revokeObjectURL(url); } catch (e) {} }, 4000);
            toast('脚本已导出', 'ri-download-line');
        } catch (e) { toast('导出失败：' + e.message, 'ri-error-warning-line'); }
    }

    function importFile(file) {
        var reader = new FileReader();
        reader.onload = function () {
            try {
                var data = JSON.parse(String(reader.result || ''));
                var incoming = Array.isArray(data) ? data : (data && Array.isArray(data.scripts) ? data.scripts : []);
                if (!incoming.length) throw new Error('文件里没有脚本数据');
                var list = rows();
                var added = 0;
                incoming.forEach(function (raw) {
                    if (!raw || !raw.findRegex) return;
                    var item = { id: '', name: raw.name, findRegex: raw.findRegex, replaceString: raw.replaceString, flags: raw.flags, placement: raw.placement, order: raw.order };
                    list.push(item);
                    added += 1;
                });
                if (!added) throw new Error('文件里的脚本都没有查找正则');
                api().save(list);
                refreshPanel();
                toast('已导入 ' + added + ' 条脚本', 'ri-upload-line');
            } catch (e) { toast('导入失败：' + e.message, 'ri-error-warning-line'); }
        };
        reader.readAsText(file);
    }

    function refreshPanel() {
        renderList();
    }

    function onPanelEsc(e) {
        if (e.key === 'Escape') { e.stopPropagation(); closePanel(); }
    }

    function closePanel() {
        if (!overlay) return;
        var el = overlay;
        overlay = null;
        el.classList.remove('show');
        setTimeout(function () { try { el.remove(); } catch (e) {} }, 180);
        document.removeEventListener('keydown', onPanelEsc, true);
    }

    function bindListEvents() {
        var host = q('rxs-list');
        if (!host || host.__rxsBound) return;
        host.__rxsBound = true;
        host.addEventListener('click', function (e) {
            var btn = e.target && e.target.closest ? e.target.closest('[data-act]') : null;
            if (!btn) return;
            var row = btn.closest('.rxs-row');
            var id = row ? row.getAttribute('data-id') : '';
            var act = btn.getAttribute('data-act');
            if (!id) return;
            if (act === 'edit') {
                var list = rows();
                for (var i = 0; i < list.length; i++) {
                    if (list[i].id === id) { fillForm(list[i]); break; }
                }
                var editor = q('rxs-editor');
                if (editor && editor.scrollIntoView) { try { editor.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); } catch (e2) {} }
            } else if (act === 'up') {
                moveById(id, -1);
            } else if (act === 'down') {
                moveById(id, 1);
            } else if (act === 'del') {
                deleteById(id);
            }
        });
        host.addEventListener('change', function (e) {
            var cb = e.target;
            if (!cb || !cb.getAttribute || cb.getAttribute('data-act') !== 'toggle') return;
            var row = cb.closest ? cb.closest('.rxs-row') : null;
            var id = row ? row.getAttribute('data-id') : '';
            if (id) toggleById(id, cb.checked);
        });
    }

    function openPanel() {
        injectStyle();
        if (overlay) return;
        overlay = document.createElement('div');
        overlay.className = 'modal-overlay show';
        overlay.style.zIndex = '3300';
        overlay.innerHTML =
            "<div class='modal-content vn-modal' style='max-width:780px'>" +
            "<div class='modal-header'>" +
            "<h2><i class='ri-code-s-slash-line'></i> 正则脚本</h2>" +
            "<button type='button' class='close-modal' id='rxs-close' aria-label='关闭'><i class='ri-close-line'></i></button>" +
            '</div>' +
            "<div class='modal-body'>" +
            "<p class='rxs-tip'>用正则表达式自动查找 / 替换。每条脚本可勾选参与哪些位置：用户输入与 AI 输出会改写聊天记录（持久生效）；世界书与提示词组装影响发给模型的上下文；聊天显示只改渲染、不动记录。</p>" +
            "<div class='rxs-hooks' id='rxs-hooks'></div>" +
            "<div class='rxs-editor' id='rxs-editor'>" +
            "<div><label style='font-size:.82em;color:#9aa0ad;'>名称</label><input type='text' id='rxs-name' placeholder='例如：折叠情绪标记'></div>" +
            "<div><label style='font-size:.82em;color:#9aa0ad;'>查找正则</label><textarea id='rxs-find' placeholder='例如：\\[emo:(\\w+)\\]'></textarea></div>" +
            "<div><label style='font-size:.82em;color:#9aa0ad;'>替换为（支持 $1 捕获组、{{match}}、{{user}}、{{char}}、{{date}}、{{time}}）</label><textarea id='rxs-replace' placeholder='例如：$1'></textarea></div>" +
            "<div class='rxs-line'>" +
            "  <div style='flex:0 0 120px;'><label style='font-size:.82em;color:#9aa0ad;'>flags</label><input type='text' id='rxs-flags' value='gi'></div>" +
            "  <div style='flex:0 0 120px;'><label style='font-size:.82em;color:#9aa0ad;'>顺序</label><input type='number' id='rxs-order' value='100'></div>" +
            '</div>' +
            "<div class='rxs-pls' id='rxs-places'></div>" +
            "<div class='rxs-acts'>" +
            "  <button class='btn btn-primary btn-sm' id='rxs-save'><i class='ri-add-line'></i> 保存脚本</button>" +
            "  <button class='btn btn-outline btn-sm' id='rxs-test'><i class='ri-play-line'></i> 试运行</button>" +
            "  <button class='btn btn-outline btn-sm' id='rxs-reset'><i class='ri-eraser-line'></i> 清空表单</button>" +
            '</div>' +
            "<textarea id='rxs-lab-in' placeholder='试运行输入（留空用默认示例文本）' style='min-height:46px;'></textarea>" +
            "<pre class='rxs-lab-out' id='rxs-lab-out' hidden></pre>" +
            '</div>' +
            "<div id='rxs-list'></div>" +
            "<div class='rxs-acts' style='margin-top:14px;border-top:1px dashed #444;padding-top:12px;'>" +
            "  <button class='btn btn-outline btn-sm' id='rxs-export'><i class='ri-download-line'></i> 导出全部</button>" +
            "  <button class='btn btn-outline btn-sm' id='rxs-import'><i class='ri-upload-line'></i> 导入 JSON</button>" +
            "  <input type='file' id='rxs-import-file' accept='.json,application/json' hidden>" +
            '</div>' +
            '</div></div>';
        document.body.appendChild(overlay);
        overlay.addEventListener('click', function (e) { if (e.target === overlay) closePanel(); });
        document.addEventListener('keydown', onPanelEsc, true);
        q('rxs-close').addEventListener('click', closePanel);
        q('rxs-save').addEventListener('click', saveFromForm);
        q('rxs-test').addEventListener('click', testRun);
        q('rxs-reset').addEventListener('click', function () { fillForm(null); });
        q('rxs-export').addEventListener('click', exportAll);
        q('rxs-import').addEventListener('click', function () { var f = q('rxs-import-file'); if (f) f.click(); });
        q('rxs-import-file').addEventListener('change', function (e) {
            var f = e.target.files && e.target.files[0];
            if (f) importFile(f);
            e.target.value = '';
        });
        renderPlaceChecks();
        fillForm(null);
        bindListEvents();
        refreshPanel();
    }

    function mountEntry() {
        var host = document.getElementById('tab-plugins');
        if (!host || host.querySelector('.rxs-entry')) return !!host;
        var block = document.createElement('div');
        block.className = 'form-group rxs-entry';
        block.style.cssText = 'border-top:1px dashed #444;padding-top:15px;margin-top:15px;';
        block.innerHTML =
            "<h3 style='margin-bottom:10px;color:#e6c78a;'><i class='ri-code-s-slash-line'></i> 正则脚本（Regex）</h3>" +
            "<p style='font-size:.85em;color:#aaa;margin-bottom:12px;line-height:1.7'>" +
            '像酒馆的正则扩展一样，用正则表达式自动整理输入、输出、世界书与显示：折叠模型多余标签、统一 Markdown 样式、' +
            '把 [emo:xx] 折成短语、自动纠错等等。支持六个执行位置与捕获组、宏变量。</p>' +
            "<button class='btn btn-outline btn-sm' id='rxs-open-btn'><i class='ri-add-line'></i> 管理正则脚本</button>";
        host.appendChild(block);
        var btn = block.querySelector('#rxs-open-btn');
        if (btn) btn.addEventListener('click', openPanel);
        return true;
    }

    function boot() {
        injectStyle();
        var tries = 0;
        (function attempt() {
            tries += 1;
            if (mountEntry()) return;
            if (tries < 40) setTimeout(attempt, 400);
        })();
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
    else boot();
})();


/* ====== chat-translate.js ====== */
/**
 * chat-translate.js —— 聊天翻译（对标「酒馆」内置翻译扩展）
 * · 每条消息气泡上的「译」按钮：点开看译文，再点收起；
 * 结果缓存在本机，重绘 / 刷新后自动恢复；
 * · 设置 → 插件 → 聊天翻译：切换引擎与目标语言、自动翻译
 * AI 新回复、翻译当前屏全部消息、清空译文缓存。
 * 重要边界：
 */
(function () {
    'use strict';
    if (window.ScriptLoader && typeof ScriptLoader.isEnabled === 'function' && !ScriptLoader.isEnabled('chat-translate.js')) return;

    var KEY = 'chatTranslateSettings';
    var CACHE_KEY = 'chatTranslateCache';
    var CACHE_MAX = 400;
    // injectStyle() 里用作 <style> 的 id；此前漏了声明，打开翻译面板时会抛
    // ReferenceError 导致面板打不开（语法检查查不出这类运行时错误，已补上）。
    var STYLE_ID = 'chat-translate-style';

    var LANGS = [
        ['zh-CN', '中文（简体）'], ['zh-TW', '中文（繁体）'], ['en', '英语'],
        ['ja', '日语'], ['ko', '韩语'], ['ru', '俄语'], ['fr', '法语'],
        ['de', '德语'], ['es', '西班牙语'], ['pt', '葡萄牙语'], ['it', '意大利语']
    ];
    var ENGINE_LABEL = { llm: 'AI 翻译', google: 'Google', mymemory: 'MyMemory', libre: 'LibreTranslate', deepl: 'DeepL' };

    var DEFAULTS = {
        enabled: true,
        autoAI: false,
        engine: 'llm',
        targetLang: 'zh-CN',
        sourceLang: 'auto',
        apiUrl: '', apiKey: '', model: '',
        libreUrl: 'https://libretranslate.com',
        deeplKey: ''
    };

    function esc(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, function (ch) {
            var c = ch.charCodeAt(0);
            if (c === 38) return '&amp;';
            if (c === 60) return '&lt;';
            if (c === 62) return '&gt;';
            if (c === 34) return '&quot;';
            return '&#39;';
        });
    }

    function toast(msg, icon) {
        try { if (typeof window.showToast === 'function') window.showToast(msg, icon || 'ri-information-line'); } catch (e) {}
    }

    function readJson(key, fallback) {
        try {
            var raw = localStorage.getItem(key);
            if (!raw) return fallback;
            var parsed = JSON.parse(raw);
            return parsed == null ? fallback : parsed;
        } catch (e) { return fallback; }
    }

    function saveJson(key, value, label) {
        try {
            if (typeof setLocalStorageSafely === 'function') return setLocalStorageSafely(key, JSON.stringify(value), label || '聊天翻译') !== false;
            localStorage.setItem(key, JSON.stringify(value));
            return true;
        } catch (e) {
            toast('保存失败：浏览器存储可能已满', 'ri-error-warning-line');
            return false;
        }
    }

    function readSettings() {
        var s = readJson(KEY, {}) || {};
        var out = {};
        for (var k in DEFAULTS) {
            if (Object.prototype.hasOwnProperty.call(DEFAULTS, k)) out[k] = (s[k] === undefined) ? DEFAULTS[k] : s[k];
        }
        return out;
    }

    function writeSettings(patch) {
        var next = readSettings();
        for (var k in patch) { if (Object.prototype.hasOwnProperty.call(patch, k)) next[k] = patch[k]; }
        saveJson(KEY, next, '聊天翻译设置');
        return next;
    }

    function langName(code) {
        for (var i = 0; i < LANGS.length; i++) { if (LANGS[i][0] === code) return LANGS[i][1]; }
        return String(code || '');
    }

    function trimSlash(u) { return String(u || '').trim().replace(/\/+$/, ''); }

    /* ---------------- 各引擎实现（返回译文，失败抛错） ---------------- */

    async function engineLLM(text, st) {
        var api = null;
        if (st.apiUrl && st.apiKey) {
            api = { apiUrl: st.apiUrl, apiKey: st.apiKey, modelName: st.model || '' };
        } else {
            try {
                if (window.EndpointStore && typeof EndpointStore.getEffectiveApiSettings === 'function') {
                    api = EndpointStore.getEffectiveApiSettings();
                }
            } catch (e) { api = null; }
            if (api && st.model) api = Object.assign({}, api, { modelName: st.model });
        }
        if (!api || !api.apiUrl || !api.apiKey) throw new Error('没有可用接口：可留空沿用当前站点，或单独填接口地址与 Key');
        if (!api.modelName) throw new Error('没有可用模型：请填模型名，或先在「AI 配置」里选好模型');
        if (!window.ApiModule || typeof ApiModule.fetchChat !== 'function') throw new Error('ApiModule 尚未就绪');
        var sys = '你是一名专业翻译。把用户提供的文本翻译成' + langName(st.targetLang) + '。' +
            '只输出译文本身，不要解释、不要加引号；保留原文的换行与 Markdown 标记（**、#、-、>）；若原文已是目标语言，原样返回。';
        var reqMessages = [
            { role: 'system', content: sys },
            { role: 'user', content: String(text) }
        ];
        // 翻译属于辅助请求：标记后不叠加提示词预设与「提示词组装」正则（见 chat-hooks.runMessages）
        reqMessages.__skipHooks = true;
        var resp = await ApiModule.fetchChat(api, reqMessages, { stream: false, max_tokens: Math.min(4000, Math.max(256, Math.ceil(String(text).length * 2))) });
        if (!resp || !resp.ok) throw new Error('接口返回错误（HTTP ' + (resp ? resp.status : '?') + '）');
        var data = await resp.json();
        var out = data && data.choices && data.choices[0] && data.choices[0].message ? String(data.choices[0].message.content || '') : '';
        if (!out.trim()) throw new Error('接口没有返回译文（可能是模型不支持或被拦截）');
        return out.trim();
    }

    async function engineGoogle(text, st) {
        var sl = (st.sourceLang && st.sourceLang !== 'auto') ? st.sourceLang : 'auto';
        var url = 'https://translate.googleapis.com/translate_a/single?client=gtx&dt=t' +
            '&sl=' + encodeURIComponent(sl) + '&tl=' + encodeURIComponent(st.targetLang) +
            '&q=' + encodeURIComponent(String(text));
        var r = await fetch(url);
        if (!r.ok) throw new Error('Google 翻译请求失败（HTTP ' + r.status + '）');
        var data = await r.json();
        var segs = data && data[0];
        if (!Array.isArray(segs)) throw new Error('Google 翻译返回格式异常');
        var out = '';
        for (var i = 0; i < segs.length; i++) { if (segs[i] && segs[i][0]) out += segs[i][0]; }
        if (!out) throw new Error('Google 翻译没有返回内容（网络可能被拦截）');
        return out;
    }

    async function engineMyMemory(text, st) {
        var src = (st.sourceLang && st.sourceLang !== 'auto') ? st.sourceLang : 'en';
        var url = 'https://api.mymemory.translated.net/get?q=' + encodeURIComponent(String(text).slice(0, 500)) +
            '&langpair=' + encodeURIComponent(src + '|' + st.targetLang);
        var r = await fetch(url);
        if (!r.ok) throw new Error('MyMemory 请求失败（HTTP ' + r.status + '）');
        var data = await r.json();
        var out = data && data.responseData ? String(data.responseData.translatedText || '') : '';
        if (!out) throw new Error('MyMemory 没有返回译文');
        return out;
    }

    async function engineLibre(text, st) {
        var base = trimSlash(st.libreUrl || DEFAULTS.libreUrl);
        var r = await fetch(base + '/translate', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                q: String(text),
                source: (st.sourceLang && st.sourceLang !== 'auto') ? st.sourceLang : 'auto',
                target: st.targetLang,
                format: 'text'
            })
        });
        if (!r.ok) throw new Error('LibreTranslate 请求失败（HTTP ' + r.status + '）');
        var data = await r.json();
        var out = data && data.translatedText ? String(data.translatedText) : '';
        if (!out) throw new Error('LibreTranslate 没有返回译文');
        return out;
    }

    async function engineDeepL(text, st) {
        if (!st.deeplKey) throw new Error('还没有填 DeepL API Key');
        var key = String(st.deeplKey).trim();
        var endpoint = key.slice(-3) === ':fx' ? 'https://api-free.deepl.com/v2/translate' : 'https://api.deepl.com/v2/translate';
        var body = new URLSearchParams();
        body.set('text', String(text));
        body.set('target_lang', String(st.targetLang).split('-')[0].toUpperCase());
        if (st.sourceLang && st.sourceLang !== 'auto') body.set('source_lang', String(st.sourceLang).split('-')[0].toUpperCase());
        var r = await fetch(endpoint, { method: 'POST', headers: { 'Authorization': 'DeepL-Auth-Key ' + key }, body: body });
        if (!r.ok) throw new Error('DeepL 请求失败（HTTP ' + r.status + '；浏览器直连常被 CORS 拦截，建议换其它引擎）');
        var data = await r.json();
        var arr = data && data.translations;
        if (!Array.isArray(arr) || !arr[0]) throw new Error('DeepL 没有返回译文');
        return String(arr[0].text || '');
    }

    async function translateText(text, opts) {
        var st = readSettings();
        var clean = String(text == null ? '' : text).trim();
        if (!clean) return { ok: false, error: '没有可翻译的内容' };
        var engine = (opts && opts.engine) || st.engine || 'llm';
        try {
            var out;
            if (engine === 'google') out = await engineGoogle(clean, st);
            else if (engine === 'mymemory') out = await engineMyMemory(clean, st);
            else if (engine === 'libre') out = await engineLibre(clean, st);
            else if (engine === 'deepl') out = await engineDeepL(clean, st);
            else out = await engineLLM(clean, st);
            return { ok: true, text: out, engine: engine, target: st.targetLang };
        } catch (e) {
            return { ok: false, error: String(e && e.message || e), engine: engine };
        }
    }

    /* ---------------- 译文缓存（按消息 ID） ---------------- */

    function readCache() {
        var c = readJson(CACHE_KEY, {});
        return (c && typeof c === 'object') ? c : {};
    }

    function getCached(id) {
        if (!id) return null;
        var c = readCache();
        return c[id] || null;
    }

    function setCached(id, rec) {
        if (!id) return;
        var c = readCache();
        c[id] = rec;
        var keys = Object.keys(c);
        if (keys.length > CACHE_MAX) {
            keys.sort(function (a, b) {
                return (Number(c[a] && c[a].at) || 0) - (Number(c[b] && c[b].at) || 0);
            });
            var drop = keys.slice(0, keys.length - CACHE_MAX);
            for (var i = 0; i < drop.length; i++) delete c[drop[i]];
        }
        saveJson(CACHE_KEY, c, '聊天翻译缓存');
    }

    function clearCache() {
        saveJson(CACHE_KEY, {}, '聊天翻译缓存');
        toast('译文缓存已清空', 'ri-delete-bin-line');
    }

    /* ---------------- 消息上的翻译按钮与译文块 ---------------- */

    var BTN_CLASS = 'ct-msg-btn';

    function baseIdOf(div) {
        var raw = (div && div.dataset && div.dataset.messageId) || '';
        return String(raw).split('-')[0];
    }

    function extractText(div) {
        var bubble = div ? div.querySelector('.bubble') : null;
        if (!bubble) return '';
        var clone = bubble.cloneNode(true);
        var drop = clone.querySelectorAll('.ct-block, .message-actions, script, style');
        for (var i = 0; i < drop.length; i++) { try { drop[i].remove(); } catch (e) {} }
        return String(clone.textContent || '').trim();
    }

    function renderBlock(div, state) {
        var host = div ? div.querySelector('.message-content') : null;
        if (!host) return;
        var block = div.querySelector('.ct-block');
        if (!block) {
            block = document.createElement('div');
            block.className = 'ct-block';
            host.appendChild(block);
        }
        block.classList.add('open');
        if (state.status === 'loading') {
            block.innerHTML = '<span class="ct-tag"><i class="ri-loader-4-line ri-spin"></i> 翻译中…</span>';
            return;
        }
        if (state.status === 'error') {
            block.innerHTML = '<span class="ct-err"><i class="ri-error-warning-line"></i> ' + esc(state.error || '翻译失败') + '</span>';
            return;
        }
        block.innerHTML = '<span class="ct-tag">' + esc(ENGINE_LABEL[state.engine] || state.engine || '') +
            ' → ' + esc(langName(state.target || readSettings().targetLang)) + '</span>' + esc(state.text || '');
    }

    var queue = Promise.resolve();
    function enqueue(fn) {
        var run = queue.then(fn, fn);
        queue = run.catch(function () {});
        return run;
    }

    function translateMessage(div, silent) {
        var id = baseIdOf(div);
        var text = extractText(div);
        if (!text) {
            if (!silent) toast('这条消息没有可翻译的文本', 'ri-information-line');
            return;
        }
        var cached = id ? getCached(id) : null;
        if (cached && cached.text) {
            renderBlock(div, { status: 'done', text: cached.text, engine: cached.engine, target: cached.target });
            return;
        }
        renderBlock(div, { status: 'loading' });
        enqueue(function () {
            return translateText(text).then(function (res) {
                if (res.ok) {
                    if (id) setCached(id, { text: res.text, engine: res.engine, target: res.target, at: Date.now() });
                    renderBlock(div, { status: 'done', text: res.text, engine: res.engine, target: res.target });
                } else {
                    renderBlock(div, { status: 'error', error: res.error });
                    if (!silent) toast('翻译失败：' + res.error, 'ri-error-warning-line');
                }
            });
        });
    }

    function makeButton(div) {
        if (!div || div.querySelector('.' + BTN_CLASS)) return;
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = BTN_CLASS;
        btn.title = '翻译这条消息（点击显示 / 收起）';
        btn.innerHTML = '<i class="ri-translate-2"></i>';
        btn.addEventListener('click', function (e) {
            e.stopPropagation();
            var block = div.querySelector('.ct-block');
            if (block && block.classList.contains('open')) { block.classList.remove('open'); return; }
            translateMessage(div, false);
        });
        var actions = div.querySelector('.message-actions');
        if (actions) { actions.appendChild(btn); return; }
        var bubble = div.querySelector('.bubble');
        if (bubble) { btn.classList.add('ct-float'); bubble.appendChild(btn); }
    }

    var scanTimer = 0;
    function scanMessages() {
        var host = document.getElementById('chat-messages');
        if (!host) return;
        var st = readSettings();
        if (!st.enabled) return;
        var list = host.querySelectorAll('.message');
        for (var i = 0; i < list.length; i++) {
            var div = list[i];
            makeButton(div);
            if (st.autoAI && div.classList.contains('other') && !div.querySelector('.ct-block')) {
                var id = baseIdOf(div);
                var c = id ? getCached(id) : null;
                if (c && c.text) renderBlock(div, { status: 'done', text: c.text, engine: c.engine, target: c.target });
                else translateMessage(div, true);
            }
        }
    }

    function observe() {
        var host = document.getElementById('chat-messages');
        if (!host || host.__ctObserved) return;
        host.__ctObserved = true;
        new MutationObserver(function () {
            clearTimeout(scanTimer);
            scanTimer = setTimeout(scanMessages, 300);
        }).observe(host, { childList: true, subtree: true });
        scanMessages();
    }

    function injectStyle() {
        if (document.getElementById(STYLE_ID)) return;
        var st = document.createElement('style');
        st.id = STYLE_ID;
        st.textContent = [
            '.message .bubble{position:relative}',
            '.ct-msg-btn{background:transparent;border:0;color:#9aa0ad;cursor:pointer;padding:4px 5px;border-radius:6px;line-height:1;font-size:1em}',
            '.ct-msg-btn:hover{color:#7fc7ff;background:rgba(255,255,255,.08)}',
            '.ct-float{position:absolute;top:4px;left:4px;opacity:0;transition:opacity .15s;background:rgba(0,0,0,.35);border:0;border-radius:6px;color:#7fc7ff;cursor:pointer;padding:3px 5px}',
            '.message.mine .ct-float{left:auto;right:4px}',
            '.message:hover .ct-float{opacity:.9}',
            '.ct-block{display:none;margin-top:8px;padding:9px 11px;border-left:3px solid #7fc7ff;border-radius:8px;background:rgba(127,199,255,.08);font-size:.92em;line-height:1.7;white-space:pre-wrap;word-break:break-word;color:#dbe6f2}',
            '.ct-block.open{display:block}',
            '.ct-tag{display:inline-block;margin-right:7px;font-size:.72em;padding:1px 7px;border-radius:999px;border:1px solid rgba(127,199,255,.5);color:#9fd3ff;white-space:nowrap}',
            '.ct-err{color:#ffb3b3;font-size:.88em}',
            '.ct-row{display:flex;align-items:center;gap:9px;padding:6px 0;font-size:.88em;color:#cfd3dd}',
            '.ct-row input[type=checkbox]{width:16px;height:16px}',
            '.ct-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:9px;margin:10px 0}',
            '.ct-fields label{font-size:.78em;color:#9aa0ad;display:block;margin-bottom:3px}',
            '.ct-fields input,.ct-fields select{width:100%;box-sizing:border-box;padding:7px;background:#20232c;border:1px solid #4a4e5c;border-radius:7px;color:#eee;font:inherit;font-size:.85em}',
            '.ct-acts{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;border-top:1px dashed #444;padding-top:12px}'
        ].join('');
        document.head.appendChild(st);
    }

    /* ---------------- 设置面板（设置 → 插件 → 聊天翻译） ---------------- */

    var overlayEl = null;

    function q(sel) { return overlayEl ? overlayEl.querySelector(sel) : null; }

    function buildFields() {
        var st = readSettings();
        var langOpts = LANGS.map(function (l) {
            return '<option value="' + esc(l[0]) + '"' + (l[0] === st.targetLang ? ' selected' : '') + '>' + esc(l[1]) + '</option>';
        }).join('');
        var engines = [['llm', 'AI 翻译（推荐）'], ['google', 'Google 翻译（免费）'], ['mymemory', 'MyMemory（免费备用）'], ['libre', 'LibreTranslate（自建实例）'], ['deepl', 'DeepL（需 Key）']];
        var engineOpts = engines.map(function (e) {
            return '<option value="' + e[0] + '"' + (e[0] === st.engine ? ' selected' : '') + '>' + e[1] + '</option>';
        }).join('');
        return '' +
            '<div class="ct-fields">' +
            '  <div><label>引擎</label><select id="ct-engine">' + engineOpts + '</select></div>' +
            '  <div><label>目标语言</label><select id="ct-target">' + langOpts + '</select></div>' +
            '</div>' +
            '<div class="ct-row"><input type="checkbox" id="ct-enabled"' + (st.enabled ? ' checked' : '') + '><label for="ct-enabled">在消息上显示「译」按钮</label></div>' +
            '<div class="ct-row"><input type="checkbox" id="ct-auto"' + (st.autoAI ? ' checked' : '') + '><label for="ct-auto">自动翻译 AI 的新回复（译文附在气泡下方，可收起）</label></div>' +
            '<details style="margin-top:6px"><summary style="font-size:.82em;color:#9aa0ad;cursor:pointer">引擎参数（AI 翻译留空 = 沿用当前站点）</summary>' +
            '  <div class="ct-fields">' +
            '    <div><label>接口地址（可留空）</label><input id="ct-url" value="' + esc(st.apiUrl) + '" placeholder="留空沿用当前站点"></div>' +
            '    <div><label>API Key（可留空）</label><input id="ct-key" value="' + esc(st.apiKey) + '" placeholder="留空沿用当前站点"></div>' +
            '    <div><label>模型（可留空）</label><input id="ct-model" value="' + esc(st.model) + '" placeholder="留空沿用当前模型"></div>' +
            '    <div><label>LibreTranslate 实例地址</label><input id="ct-libre" value="' + esc(st.libreUrl) + '"></div>' +
            '    <div><label>DeepL API Key</label><input id="ct-deepl" value="' + esc(st.deeplKey) + '"></div>' +
            '  </div>' +
            '</details>' +
            '<div class="ct-acts">' +
            '  <button class="btn btn-primary btn-sm" id="ct-save"><i class="ri-save-line"></i> 保存设置</button>' +
            '  <button class="btn btn-outline btn-sm" id="ct-all"><i class="ri-translate-2"></i> 翻译当前屏全部消息</button>' +
            '  <button class="btn btn-outline btn-sm" id="ct-clear"><i class="ri-delete-bin-line"></i> 清空译文缓存</button>' +
            '</div>';
    }

    function saveFromPanel() {
        writeSettings({
            enabled: q('#ct-enabled') ? q('#ct-enabled').checked : true,
            autoAI: q('#ct-auto') ? q('#ct-auto').checked : false,
            engine: q('#ct-engine') ? q('#ct-engine').value : 'llm',
            targetLang: q('#ct-target') ? q('#ct-target').value : 'zh-CN',
            apiUrl: q('#ct-url') ? q('#ct-url').value.trim() : '',
            apiKey: q('#ct-key') ? q('#ct-key').value.trim() : '',
            model: q('#ct-model') ? q('#ct-model').value.trim() : '',
            libreUrl: q('#ct-libre') ? q('#ct-libre').value.trim() : '',
            deeplKey: q('#ct-deepl') ? q('#ct-deepl').value.trim() : ''
        });
        toast('聊天翻译设置已保存', 'ri-check-line');
    }

    function onEsc(e) {
        if (e.key === 'Escape') { e.stopPropagation(); closePanel(); }
    }

    function closePanel() {
        if (!overlayEl) return;
        var el = overlayEl;
        overlayEl = null;
        el.classList.remove('show');
        setTimeout(function () { try { el.remove(); } catch (e) {} }, 180);
        document.removeEventListener('keydown', onEsc, true);
    }

    function openPanel() {
        injectStyle();
        if (overlayEl) return;
        overlayEl = document.createElement('div');
        overlayEl.className = 'modal-overlay show';
        overlayEl.style.zIndex = '3300';
        overlayEl.innerHTML =
            '<div class="modal-content vn-modal" style="max-width:640px">' +
            '<div class="modal-header"><h2><i class="ri-translate-2"></i> 聊天翻译</h2>' +
            '<button type="button" class="close-modal" id="ct-close" aria-label="关闭"><i class="ri-close-line"></i></button></div>' +
            '<div class="modal-body">' +
            '<p style="font-size:.82em;color:#8d93a1;margin:0 0 10px;line-height:1.7">译文只用于显示：不改聊天记录、不影响上下文与导出。每条消息气泡上的「译」按钮可随时查看 / 收起；结果按消息缓存在本机，刷新后自动恢复。</p>' +
            buildFields() +
            '</div></div>';
        document.body.appendChild(overlayEl);
        overlayEl.addEventListener('click', function (e) { if (e.target === overlayEl) closePanel(); });
        document.addEventListener('keydown', onEsc, true);
        q('#ct-close').addEventListener('click', closePanel);
        q('#ct-save').addEventListener('click', saveFromPanel);
        q('#ct-clear').addEventListener('click', clearCache);
        q('#ct-all').addEventListener('click', function () {
            var host = document.getElementById('chat-messages');
            if (!host) return;
            var list = host.querySelectorAll('.message.other');
            if (!list.length) { toast('当前没有可翻译的消息', 'ri-information-line'); return; }
            var count = 0;
            for (var i = 0; i < list.length; i++) { translateMessage(list[i], true); count += 1; }
            toast('已开始翻译 ' + count + ' 条消息，请稍候…', 'ri-loader-4-line');
        });
    }

    function mountEntry() {
        var host = document.getElementById('tab-plugins');
        if (!host || host.querySelector('.ct-entry')) return !!host;
        var block = document.createElement('div');
        block.className = 'form-group ct-entry';
        block.style.cssText = 'border-top:1px dashed #444;padding-top:15px;margin-top:15px;';
        block.innerHTML =
            '<h3 style="margin-bottom:10px;color:#e6c78a;"><i class="ri-translate-2"></i> 聊天翻译</h3>' +
            '<p style="font-size:.85em;color:#aaa;margin-bottom:12px;line-height:1.7">点消息上的「译」按钮即可查看译文；也可以自动翻译 AI 的每条新回复。支持 AI / Google / MyMemory / LibreTranslate / DeepL 五种引擎，译文只用于显示。</p>' +
            '<button class="btn btn-outline btn-sm" id="ct-open-btn"><i class="ri-settings-4-line"></i> 翻译设置</button>';
        host.appendChild(block);
        var btn = block.querySelector('#ct-open-btn');
        if (btn) btn.addEventListener('click', openPanel);
        return true;
    }

    function boot() {
        injectStyle();
        observe();
        var tries = 0;
        (function attempt() {
            tries += 1;
            if (mountEntry()) return;
            if (tries < 40) setTimeout(attempt, 400);
        })();
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
    else boot();

    window.ChatTranslate = {
        translateText: translateText,
        translateMessage: translateMessage,
        clearCache: clearCache,
        getSettings: readSettings,
        saveSettings: writeSettings,
        openPanel: openPanel,
        LANGS: LANGS
    };
})();


/* ====== chat-checkpoints.js ====== */
/**
 * chat-checkpoints.js —— 聊天检查点与消息分叉
 * · 创建检查点：把当前对话拍一张命名快照，不切换、不改动现有内容，
 * 之后随时可以整体恢复；
 * · 从此消息分叉：保留到指定消息为止的剧情，截断后面的内容，
 * 用于「回到岔路口换一种走法」；
 * · 「恢复」与「分叉」执行前都会自动再存一张「自动快照」，
 * 误操作可以反悔。
 * 为什么不做「克隆成新对话」：新建对话需要直接写 threadManager 的
 * · 每条消息操作栏的「检查点 / 分叉」按钮；
 * · 设置 → 插件 → 聊天检查点：列表、恢复、导出、导入、删除。
 * 存储：localStorage['chatCheckpoints']，最多保留 20 个。
 */
(function () {
    'use strict';
    if (window.ScriptLoader && typeof ScriptLoader.isEnabled === 'function' && !ScriptLoader.isEnabled('chat-checkpoints.js')) return;

    var KEY = 'chatCheckpoints';
    var MAX_ITEMS = 20;
    var MAX_MESSAGES = 2000;
    var scanTimer = 0;

    /* ---------------- 基础工具 ---------------- */

    function esc(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, function (ch) {
            var c = ch.charCodeAt(0);
            if (c === 38) return '&amp;';
            if (c === 60) return '&lt;';
            if (c === 62) return '&gt;';
            if (c === 34) return '&quot;';
            return '&#39;';
        });
    }

    function toast(msg, icon) {
        try { if (typeof window.showToast === 'function') window.showToast(msg, icon || 'ri-information-line'); }
        catch (e) {}
    }

    function readJson(key, fallback) {
        try {
            var raw = localStorage.getItem(key);
            if (!raw) return fallback;
            var parsed = JSON.parse(raw);
            return parsed == null ? fallback : parsed;
        } catch (e) { return fallback; }
    }

    function writeJson(key, value) {
        try {
            if (typeof setLocalStorageSafely === 'function') return setLocalStorageSafely(key, JSON.stringify(value), '聊天检查点') !== false;
            localStorage.setItem(key, JSON.stringify(value));
            return true;
        } catch (e) {
            toast('保存失败：浏览器存储可能已满', 'ri-error-warning-line');
            return false;
        }
    }

    function uid() { return 'cp_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8); }
    function pad2(n) { return (n < 10 ? '0' : '') + n; }

    function fmtTime(ts) {
        var d = new Date(Number(ts) || Date.now());
        return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) + ' ' + pad2(d.getHours()) + ':' + pad2(d.getMinutes());
    }

    function stamp() { return fmtTime(Date.now()); }

    /* ---------------- 宿主接口 ---------------- */

    function friendId() {
        try { if (window.currentFriendId != null) return String(window.currentFriendId); } catch (e) {}
        var el = document.querySelector('.friend-item.active');
        if (el) {
            var attr = el.getAttribute('data-friend-id') || el.getAttribute('data-id');
            if (attr) return String(attr);
        }
        return '';
    }

    function threadInfo() {
        try { if (typeof window.getCurrentThread === 'function') return window.getCurrentThread(); } catch (e) {}
        return null;
    }

    function persistThreads() {
        try { if (typeof window.saveThreadManager === 'function') window.saveThreadManager(); } catch (e) {}
    }

    function rerender() {
        var fid = friendId();
        try { if (fid && typeof window.renderMessages === 'function') window.renderMessages(fid); } catch (e) {}
    }

    function cloneMessages(list) {
        var safe = (list || []).slice(0, MAX_MESSAGES);
        try { return JSON.parse(JSON.stringify(safe)); } catch (e) { return safe; }
    }

    /* ---------------- 数据层 ---------------- */

    function loadAll() {
        var data = readJson(KEY, null);
        var list = data && Array.isArray(data.list) ? data.list : [];
        return list.filter(function (c) { return c && c.id && Array.isArray(c.messages); });
    }

    function saveAll(list) {
        return writeJson(KEY, { version: 1, list: (list || []).slice(0, MAX_ITEMS) });
    }

    function listForFriend(fid) {
        return loadAll().filter(function (c) { return String(c.friendId || '') === String(fid || ''); });
    }

    function findById(id) {
        var list = loadAll();
        for (var i = 0; i < list.length; i++) { if (list[i].id === id) return list[i]; }
        return null;
    }

    function snapshotCurrent(name) {
        var thread = threadInfo();
        if (!thread) { toast('当前没有打开的对话', 'ri-error-warning-line'); return null; }
        if (!Array.isArray(thread.messages) || !thread.messages.length) {
            toast('当前对话还是空的，无法创建检查点', 'ri-error-warning-line');
            return null;
        }
        var record = {
            id: uid(),
            name: String(name || '').trim() || ('检查点 · ' + stamp()),
            friendId: friendId(),
            threadId: thread.id,
            threadName: String(thread.name || ''),
            createdAt: Date.now(),
            count: thread.messages.length,
            messages: cloneMessages(thread.messages)
        };
        var list = loadAll();
        list.unshift(record);
        if (saveAll(list)) {
            toast('已创建检查点「' + record.name + '」', 'ri-bookmark-line');
            refreshPanel();
        }
        return record;
    }

    function restore(id) {
        var record = findById(id);
        if (!record) { toast('检查点不存在，可能已被删除', 'ri-error-warning-line'); return false; }
        var thread = threadInfo();
        if (!thread) { toast('当前没有打开的对话', 'ri-error-warning-line'); return false; }
        snapshotCurrent('自动快照 · 恢复前 ' + stamp());
        thread.messages = cloneMessages(record.messages);
        persistThreads();
        rerender();
        toast('已恢复到检查点「' + record.name + '」', 'ri-history-line');
        return true;
    }

    function locateIndex(thread, messageId) {
        if (!thread || !Array.isArray(thread.messages)) return -1;
        for (var i = 0; i < thread.messages.length; i++) {
            var m = thread.messages[i] || {};
            var key = (m.id != null ? m.id : m.timestamp);
            if (String(key) === String(messageId)) return i;
        }
        return -1;
    }

    function forkFromMessage(messageId) {
        var thread = threadInfo();
        if (!thread || !Array.isArray(thread.messages)) { toast('当前没有打开的对话', 'ri-error-warning-line'); return false; }
        var idx = locateIndex(thread, messageId);
        if (idx < 0) { toast('没有找到这条消息', 'ri-error-warning-line'); return false; }
        var cut = thread.messages.length - idx - 1;
        if (cut <= 0) { toast('这已经是最后一条消息，不需要分叉', 'ri-information-line'); return false; }
        var run = function () {
            snapshotCurrent('自动快照 · 分叉前 ' + stamp());
            var cur = threadInfo();
            var j = locateIndex(cur, messageId);
            if (j < 0) return;
            cur.messages = cur.messages.slice(0, j + 1);
            persistThreads();
            rerender();
            toast('已分叉：截断了后面的 ' + cut + ' 条内容（分叉前的状态已自动存为快照）', 'ri-git-branch-line');
            refreshPanel();
        };
        var msg = '将保留到这条消息为止的内容，并删除它后面的 ' + cut + ' 条消息。\n分叉前的完整对话会自动存成一个快照，随时可以恢复。';
        if (window.Dlg && typeof window.Dlg.confirm === 'function') {
            window.Dlg.confirm({ title: '从此消息分叉', message: msg, okText: '分叉' }).then(function (yes) { if (yes) run(); });
        } else if (window.confirm(msg)) { run(); }
        return true;
    }

    function remove(id) {
        var next = loadAll().filter(function (c) { return c.id !== id; });
        saveAll(next);
        refreshPanel();
        toast('检查点已删除', 'ri-delete-bin-line');
    }

    /* ---------------- 每条消息的「检查点 / 分叉」入口 ---------------- */

    var ACTION_CLASS = 'ccp-msg-btn';

    function makeMsgButton(messageDiv) {
        if (!messageDiv || messageDiv.querySelector('.' + ACTION_CLASS)) return;
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = ACTION_CLASS;
        btn.title = '检查点 / 分叉';
        btn.innerHTML = '<i class="ri-git-branch-line"></i>';
        btn.addEventListener('click', function (e) {
            e.stopPropagation();
            openMessageMenu(messageDiv);
        });
        var actions = messageDiv.querySelector('.message-actions');
        if (actions) { actions.appendChild(btn); return; }
        var bubble = messageDiv.querySelector('.bubble');
        if (bubble) {
            bubble.style.position = bubble.style.position || 'relative';
            btn.classList.add('ccp-float');
            bubble.appendChild(btn);
        }
    }

    function askName() {
        if (window.Dlg && typeof window.Dlg.prompt === 'function') {
            return window.Dlg.prompt({
                title: '创建检查点',
                message: '给这个检查点取个名字，留空则自动用时间命名。',
                placeholder: '例如：决战前夜',
                okText: '创建'
            });
        }
        var v = window.prompt('检查点名称（可留空）');
        return Promise.resolve(v === null ? null : v);
    }

    function confirmBox(title, message, okText) {
        if (window.Dlg && typeof window.Dlg.confirm === 'function') {
            return Promise.resolve(window.Dlg.confirm({ title: title, message: message, okText: okText || '确定' }));
        }
        return Promise.resolve(window.confirm(title + '\n\n' + message));
    }

    function openMessageMenu(messageDiv) {
        var mid = messageDiv && messageDiv.dataset ? messageDiv.dataset.messageId : null;
        if (mid == null) { toast('这条消息还没有编号，暂时无法操作', 'ri-error-warning-line'); return; }
        var buttons = [
            { label: '创建检查点（不改动对话）', value: 'cp', icon: 'ri-bookmark-line' },
            { label: '从此消息分叉（截断后面的内容）', value: 'fork', icon: 'ri-git-branch-line' }
        ];
        var pick;
        if (window.Dlg && typeof window.Dlg.choice === 'function') {
            pick = window.Dlg.choice({ title: '这条消息', message: '要对当前对话做什么？', buttons: buttons });
        } else {
            pick = Promise.resolve(window.confirm('点「确定」= 创建检查点；点「取消」= 从此消息分叉') ? 'cp' : 'fork');
        }
        pick.then(function (val) {
            if (val === 'cp') {
                askName().then(function (name) { if (name == null) return; snapshotCurrent(String(name)); });
            } else if (val === 'fork') {
                forkFromMessage(mid);
            }
        });
    }

    function scanMessages() {
        var host = document.getElementById('chat-messages');
        if (!host) return;
        var list = host.querySelectorAll('.message');
        for (var i = 0; i < list.length; i++) makeMsgButton(list[i]);
    }

    function observeChat() {
        var host = document.getElementById('chat-messages');
        if (!host || host.__ccpObserved) return;
        host.__ccpObserved = true;
        var mo = new MutationObserver(function () {
            clearTimeout(scanTimer);
            scanTimer = setTimeout(scanMessages, 120);
        });
        mo.observe(host, { childList: true, subtree: true });
        scanMessages();
    }

    /* ---------------- 检查点面板与设置入口 ---------------- */

    var overlayEl = null;

    function injectCcpStyle() {
        if (document.getElementById('ccp-style')) return;
        var st = document.createElement('style');
        st.id = 'ccp-style';
        st.textContent = [
            '.message-actions .ccp-msg-btn{background:transparent;border:0;color:#9aa0ad;cursor:pointer;padding:4px 5px;border-radius:6px;line-height:1;font-size:1em}',
            '.message-actions .ccp-msg-btn:hover{color:#e6c78a;background:rgba(255,255,255,.08)}',
            '.message .bubble{position:relative}',
            '.ccp-float{position:absolute;top:4px;right:4px;opacity:0;transition:opacity .15s;background:rgba(0,0,0,.35);border:0;border-radius:6px;color:#e6c78a;cursor:pointer;padding:3px 5px}',
            '.message:hover .ccp-float{opacity:.9}',
            '.ccp-row{display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid #3b3f4b;border-radius:10px;margin-bottom:8px;background:rgba(255,255,255,.03)}',
            '.ccp-row .ccp-main{flex:1 1 auto;min-width:0}',
            '.ccp-row .ccp-name{color:#e6c78a;font-size:.92em;word-break:break-all}',
            '.ccp-row .ccp-meta{color:#8d93a1;font-size:.75em;margin-top:3px}',
            '.ccp-btn{background:transparent;border:1px solid #4a4e5c;color:#cfd3dd;border-radius:8px;padding:5px 10px;font-size:.8em;cursor:pointer;white-space:nowrap}',
            '.ccp-btn:hover{border-color:#e6c78a;color:#e6c78a}',
            '.ccp-btn.danger:hover{border-color:#f06b78;color:#f06b78}'
        ].join('');
        document.head.appendChild(st);
    }

    function onPanelEsc(e) {
        if (e.key === 'Escape') { e.stopPropagation(); closePanel(); }
    }

    function closePanel() {
        if (!overlayEl) return;
        var el = overlayEl;
        overlayEl = null;
        el.classList.remove('show');
        setTimeout(function () { try { el.remove(); } catch (e) {} }, 180);
        document.removeEventListener('keydown', onPanelEsc, true);
    }

    function refreshPanel() {
        if (!overlayEl) return;
        var host = overlayEl.querySelector('#ccp-list');
        if (!host) return;
        var list = listForFriend(friendId());
        if (!list.length) {
            host.innerHTML = "<p style='color:#8d93a1;font-size:.85em;text-align:center;padding:18px 0'>" +
                '当前角色还没有检查点。点上方「创建检查点」，或在任意消息的操作栏里用分叉按钮。</p>';
            return;
        }
        var html = '';
        list.forEach(function (c) {
            html += "<div class='ccp-row'>" +
                "<div class='ccp-main'>" +
                "<div class='ccp-name'>" + esc(c.name) + '</div>' +
                "<div class='ccp-meta'>" + esc(fmtTime(c.createdAt)) + ' · ' + Number(c.count) + ' 条消息' +
                (c.threadName ? ' · ' + esc(c.threadName) : '') + '</div>' +
                '</div>' +
                "<button class='ccp-btn' data-cp-act='restore' data-cp-id='" + esc(c.id) + "'><i class='ri-history-line'></i> 恢复</button>" +
                "<button class='ccp-btn danger' data-cp-act='del' data-cp-id='" + esc(c.id) + "'><i class='ri-delete-bin-line'></i></button>" +
                '</div>';
        });
        host.innerHTML = html;
    }

    function exportAll() {
        var list = listForFriend(friendId());
        if (!list.length) { toast('当前角色还没有可导出的检查点', 'ri-error-warning-line'); return; }
        try {
            var payload = { app: 'MySW', kind: 'chatCheckpoints', version: 1, exportedAt: Date.now(), friendId: friendId(), list: list };
            var blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
            var url = URL.createObjectURL(blob);
            var a = document.createElement('a');
            a.href = url;
            a.download = 'mysw-checkpoints-' + Date.now() + '.json';
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(function () { try { URL.revokeObjectURL(url); } catch (e) {} }, 4000);
            toast('检查点已导出', 'ri-download-line');
        } catch (e) { toast('导出失败：' + e.message, 'ri-error-warning-line'); }
    }

    function importFile(file) {
        var reader = new FileReader();
        reader.onload = function () {
            try {
                var data = JSON.parse(String(reader.result || ''));
                var incoming = Array.isArray(data) ? data : (data && Array.isArray(data.list) ? data.list : []);
                if (!incoming.length) throw new Error('文件里没有检查点数据');
                var existing = loadAll();
                var usedIds = {};
                existing.forEach(function (c) { usedIds[c.id] = true; });
                var added = 0;
                incoming.forEach(function (raw) {
                    if (!raw || !Array.isArray(raw.messages) || !raw.messages.length) return;
                    var c = {
                        id: String(raw.id || uid()),
                        name: String(raw.name || ('导入的检查点 · ' + stamp())),
                        friendId: friendId(),
                        threadId: raw.threadId || null,
                        threadName: String(raw.threadName || ''),
                        createdAt: Number(raw.createdAt) || Date.now(),
                        count: raw.messages.length,
                        messages: cloneMessages(raw.messages)
                    };
                    if (usedIds[c.id]) c.id = uid();
                    usedIds[c.id] = true;
                    existing.unshift(c);
                    added += 1;
                });
                if (!added) throw new Error('文件里的检查点都是空的');
                saveAll(existing);
                refreshPanel();
                toast('已导入 ' + added + ' 个检查点', 'ri-upload-line');
            } catch (e) {
                toast('导入失败：' + e.message, 'ri-error-warning-line');
            }
        };
        reader.readAsText(file);
    }

    function openPanel() {
        injectCcpStyle();
        if (overlayEl) return;
        overlayEl = document.createElement('div');
        overlayEl.className = 'modal-overlay show';
        overlayEl.style.zIndex = '3200';
        overlayEl.innerHTML =
            "<div class='modal-content' style='max-width:640px'>" +
            "<div class='modal-header'>" +
            "<h2><i class='ri-git-branch-line'></i> 聊天检查点</h2>" +
            "<button type='button' class='close-modal' id='ccp-close' aria-label='关闭'><i class='ri-close-line'></i></button>" +
            '</div>' +
            "<div class='modal-body'>" +
            "<p style='font-size:.82em;color:#8d93a1;margin:0 0 12px;line-height:1.7'>" +
            '检查点是当前对话的完整快照（不切换、不改动现有内容），之后可以随时整体恢复；' +
            '「恢复」与消息分叉执行前都会自动再存一张快照，误操作可以反悔。</p>' +
            "<div style='display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px'>" +
            "<button class='btn btn-primary btn-sm' id='ccp-create'><i class='ri-add-line'></i> 创建检查点</button>" +
            "<button class='btn btn-outline btn-sm' id='ccp-export'><i class='ri-download-line'></i> 导出</button>" +
            "<button class='btn btn-outline btn-sm' id='ccp-import'><i class='ri-upload-line'></i> 导入</button>" +
            "<input type='file' id='ccp-import-file' accept='.json,application/json' hidden>" +
            '</div>' +
            "<div id='ccp-list'></div>" +
            '</div>' +
            '</div>';
        document.body.appendChild(overlayEl);
        overlayEl.addEventListener('click', function (e) { if (e.target === overlayEl) closePanel(); });
        document.addEventListener('keydown', onPanelEsc, true);
        overlayEl.querySelector('#ccp-close').addEventListener('click', closePanel);
        overlayEl.querySelector('#ccp-create').addEventListener('click', function () {
            askName().then(function (name) { if (name == null) return; snapshotCurrent(String(name)); refreshPanel(); });
        });
        overlayEl.querySelector('#ccp-export').addEventListener('click', exportAll);
        overlayEl.querySelector('#ccp-import').addEventListener('click', function () {
            var f = overlayEl.querySelector('#ccp-import-file');
            if (f) f.click();
        });
        overlayEl.querySelector('#ccp-import-file').addEventListener('change', function (e) {
            var f = e.target.files && e.target.files[0];
            if (f) importFile(f);
            e.target.value = '';
        });
        overlayEl.querySelector('#ccp-list').addEventListener('click', function (e) {
            var btn = e.target && e.target.closest ? e.target.closest('[data-cp-act]') : null;
            if (!btn) return;
            var id = btn.getAttribute('data-cp-id');
            var act = btn.getAttribute('data-cp-act');
            if (act === 'restore') {
                confirmBox('恢复检查点', '当前对话将被替换为这个快照；现在的状态会自动存成一张新快照。', '恢复').then(function (yes) {
                    if (yes) { restore(id); refreshPanel(); }
                });
            } else if (act === 'del') {
                confirmBox('删除检查点', '删除后无法恢复（不影响聊天记录本身）。', '删除').then(function (yes) {
                    if (yes) { remove(id); refreshPanel(); }
                });
            }
        });
        refreshPanel();
    }

    function mountEntry() {
        var host = document.getElementById('tab-ext') || document.getElementById('tab-plugins');
        if (!host) return false;
        if (host.querySelector('.ccp-entry')) return true;
        var block = document.createElement('div');
        block.className = 'form-group ccp-entry';
        block.style.cssText = 'border-top:1px dashed #444;padding-top:15px;margin-top:15px;';
        block.innerHTML =
            "<h3 style='margin-bottom:10px;color:#e6c78a;'><i class='ri-git-branch-line'></i> 聊天检查点 / 分叉</h3>" +
            "<p style='font-size:.85em;color:#aaa;margin-bottom:12px;line-height:1.7'>" +
            '给当前对话拍命名快照、随时整体恢复；或在任意一条消息的操作栏里「从此分叉」——' +
            '保留到那条为止、截断后面的剧情，用来探索不同走向。每次恢复 / 分叉前会自动再存一张快照。</p>' +
            "<button class='btn btn-outline btn-sm' id='ccp-open-btn'><i class='ri-bookmark-line'></i> 打开检查点列表</button>";
        host.appendChild(block);
        var btn = block.querySelector('#ccp-open-btn');
        if (btn) btn.addEventListener('click', openPanel);
        return true;
    }

    function bootCheckpoints() {
        injectCcpStyle();
        observeChat();
        var tries = 0;
        (function attempt() {
            tries += 1;
            if (mountEntry()) return;
            if (tries < 40) setTimeout(attempt, 400);
        })();
    }

    if (!window.ChatCheckpoints) window.ChatCheckpoints = {};
    window.ChatCheckpoints.create = snapshotCurrent;
    window.ChatCheckpoints.restore = restore;
    window.ChatCheckpoints.forkFrom = forkFromMessage;
    window.ChatCheckpoints.list = listForFriend;
    window.ChatCheckpoints.remove = remove;
    window.ChatCheckpoints.openPanel = openPanel;

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bootCheckpoints);
    else bootCheckpoints();
})();


/* ====== prompt-presets.js ====== */
/**
 * prompt-presets.js —— 提示词预设系统（对标「酒馆」预设管理器）
 * · 主提示词（Main Prompt）：拼在 system 最前面，设定全局行为准则；
 * · 辅助提示词（Auxiliary）：拼在 system 末尾，补充风格 / 格式要求；
 * · 历史后指令（Post-History）：放在最后一条消息之后，越靠近模型
 * 最后看到的文字服从性越高，适合「只用中文回答」这类硬约束。
 * 实现方式：复用 chat-hooks.js 的 promptAssembly 阶段（请求发出前直接
 */
(function () {
    'use strict';
    if (window.ScriptLoader && typeof ScriptLoader.isEnabled === 'function' && !ScriptLoader.isEnabled('prompt-presets.js')) return;

    var KEY = 'promptPresets';

        /**
     * ---------------- 与酒馆（SillyTavern）预设互转 ----------------
     * · 普通提示（injection_position=0，跟在提示词列表里）→ 主提示词
     * · 深度注入（injection_position=1，注入到对话里）→ 历史后指令
     * （本站的历史后指令就是拼在最后一条消息之后的，语义最接近）
     * · 站内没有独立位置可放的，才塞进辅助提示词
     * 参数（温度等）不迁移：本站的温度在「AI 配置」里统一管理，混进来反而会被覆盖。
     * prompt_order 里那些 charDescription / chatHistory 之类是酒馆的占位符（marker），
     */
    var ST_MARKER_IDS = ['worldInfoBefore', 'worldInfoAfter', 'charDescription', 'charPersonality',
        'personaDescription', 'scenario', 'enhanceDefinitions', 'chatHistory', 'dialogueExamples'];

    function isSillyTavernPreset(obj) {
        if (!obj || typeof obj !== 'object') return false;
        if (!Array.isArray(obj.prompts) || !obj.prompts.length) return false;
        return Array.isArray(obj.prompt_order) || obj.temperature !== undefined || obj.top_p !== undefined
            || obj.max_context_unlocked !== undefined || obj.openai_max_tokens !== undefined;
    }

    function stOrderList(obj) {
        var po = obj && obj.prompt_order;
        if (!Array.isArray(po) || !po.length) return [];
        // 两种形态：老的 [{identifier, enabled}]，新的 [{character_id, order:[...]}]
        if (po[0] && Array.isArray(po[0].order)) return po[0].order;
        return po;
    }

    function fromSillyTavernPreset(obj, nameHint) {
        var order = stOrderList(obj);
        var byId = {};
        (obj.prompts || []).forEach(function (it) {
            if (it && it.identifier) byId[it.identifier] = it;
        });
        // 没有 prompt_order 时按 prompts 原顺序，全部视为启用
        var seq = order.length
            ? order.map(function (o) { return { id: o.identifier || o.id, enabled: o.enabled !== false }; })
            : (obj.prompts || []).map(function (it) { return { id: it.identifier, enabled: it.enabled !== false }; });

        var mainParts = [], postParts = [], auxParts = [];
        var seen = {};
        seq.forEach(function (row) {
            var id = row.id;
            if (!id || seen[id]) return;
            seen[id] = 1;
            if (ST_MARKER_IDS.indexOf(id) >= 0) return;      // 占位符，不是文本
            var p = byId[id];
            if (!p || p.marker === true) return;
            var content = String(p.content || '').trim();
            if (!content) return;
            if (!row.enabled) return;
            var inChat = Number(p.injection_position) === 1 || /jailbreak|post.?history/i.test(id);
            if (inChat) postParts.push(content);
            else if (p.role === 'assistant') auxParts.push(content);
            else mainParts.push(content);
        });

        return {
            name: String(obj.name || nameHint || '酒馆预设').slice(0, 40),
            main: mainParts.join('\n\n'),
            auxiliary: auxParts.join('\n\n'),
            postHistory: postParts.join('\n\n'),
            enabled: true
        };
    }

    function toSillyTavernPreset(preset) {
        var main = String(preset.main || '');
        var aux = String(preset.auxiliary || '');
        var post = String(preset.postHistory || '');
        var prompts = [
            {
                identifier: 'main', name: 'Main Prompt', system_prompt: true, role: 'system',
                content: main, injection_position: 0, injection_depth: 4, forbid_overrides: false
            },
            {
                identifier: 'myswAux', name: 'MySW 辅助提示词', system_prompt: false, role: 'system',
                content: aux, injection_position: 0, injection_depth: 4, forbid_overrides: false
            },
            {
                identifier: 'jailbreak', name: 'MySW 历史后指令', system_prompt: false, role: 'system',
                content: post, injection_position: 1, injection_depth: 0, forbid_overrides: false
            }
        ];
        // 酒馆会按 prompt_order 排出真正发给模型的内容；空文本的条目直接置为未启用，
        // 免得在酒馆里多出两条空白提示词碍事。
        var order = [
            { identifier: 'worldInfoBefore', enabled: true },
            { identifier: 'main', enabled: !!main.trim() },
            { identifier: 'charDescription', enabled: true },
            { identifier: 'charPersonality', enabled: true },
            { identifier: 'personaDescription', enabled: true },
            { identifier: 'scenario', enabled: true },
            { identifier: 'myswAux', enabled: !!aux.trim() },
            { identifier: 'worldInfoAfter', enabled: true },
            { identifier: 'dialogueExamples', enabled: true },
            { identifier: 'chatHistory', enabled: true },
            { identifier: 'jailbreak', enabled: !!post.trim() }
        ];
        return {
            name: preset.name || 'MySW 预设',
            temperature: 0.85,
            top_p: 0.95,
            top_k: 0,
            repetition_penalty: 1.05,
            openai_max_tokens: 2048,
            openai_max_context: 32768,
            max_context_unlocked: false,
            prompts: prompts,
            prompt_order: [{ character_id: 100000, order: order }],
            extensions: { mysw: { exportedAt: new Date().toISOString() } }
        };
    }

    /* 供「酒馆整包搬家」调用：把一批酒馆预设对象转成本站预设并存下来。
       policy：overwrite 同名覆盖 / copy 都保留（重名加序号） / skip 跳过同名 */
    function importSillyTavernObjects(objs, options) {
        var opts = options || {};
        var policy = ['overwrite', 'copy', 'skip'].indexOf(opts.policy) >= 0 ? opts.policy : 'copy';
        var data = loadAll();
        var added = 0, skipped = 0;
        (objs || []).forEach(function (obj) {
            var conv = fromSillyTavernPreset(obj, opts.nameHint);
            if (!conv.main && !conv.auxiliary && !conv.postHistory) return;
            var sameIdx = -1;
            for (var i = 0; i < data.presets.length; i++) {
                if (String(data.presets[i].name || '').trim() === String(conv.name || '').trim()) { sameIdx = i; break; }
            }
            if (sameIdx >= 0 && policy === 'skip') { skipped++; return; }
            if (sameIdx >= 0 && policy === 'overwrite') {
                conv.id = data.presets[sameIdx].id;
                data.presets[sameIdx] = normalizePreset(conv);
                added++;
                return;
            }
            if (sameIdx >= 0) {
                var base = conv.name, n = 2;
                var names = data.presets.map(function (p) { return p.name; });
                while (names.indexOf(conv.name) >= 0) { conv.name = base + ' (' + n + ')'; n++; }
            }
            conv.id = 'pp_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
            data.presets.push(normalizePreset(conv));
            added++;
        });
        if (added || skipped) saveAll(data);
        try { if (overlay) renderList(); } catch (e) { }
        return { added: added, skipped: skipped };
    }

    /* 把「当前启用」的预设导出成酒馆预设文件：直接丢进 SillyTavern 的
       「预设 → 导入」就能用（提示词、启用顺序都在，采样参数给的是通用默认值）。 */
    function exportAsSillyTavern() {
        var p = activePreset();
        if (!p) { toast('还没有可导出的预设', 'ri-information-line'); return; }
        if (!String(p.main || '').trim() && !String(p.auxiliary || '').trim() && !String(p.postHistory || '').trim()) {
            toast('当前预设是空白的，导出到酒馆没有内容', 'ri-information-line');
            return;
        }
        try {
            var payload = toSillyTavernPreset(p);
            var blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
            var url = URL.createObjectURL(blob);
            var a = document.createElement('a');
            a.href = url;
            a.download = (p.name || 'preset').replace(/[\\/:*?"<>|]/g, '_') + '_酒馆预设.json';
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(function () { try { URL.revokeObjectURL(url); } catch (e) { } }, 4000);
            toast('已导出酒馆预设（在酒馆「预设 → 导入」里选它）', 'ri-download-line');
        } catch (e) {
            toast('导出失败：' + e.message, 'ri-error-warning-line');
        }
    }


    function esc(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, function (ch) {
            var c = ch.charCodeAt(0);
            if (c === 38) return '&amp;';
            if (c === 60) return '&lt;';
            if (c === 62) return '&gt;';
            if (c === 34) return '&quot;';
            return '&#39;';
        });
    }

    function toast(msg, icon) {
        try { if (typeof window.showToast === 'function') window.showToast(msg, icon || 'ri-information-line'); } catch (e) {}
    }

    function readJson(key, fallback) {
        try {
            var raw = localStorage.getItem(key);
            if (!raw) return fallback;
            var parsed = JSON.parse(raw);
            return parsed == null ? fallback : parsed;
        } catch (e) { return fallback; }
    }

    function saveJson(value) {
        try {
            if (typeof setLocalStorageSafely === 'function') {
                // 【关键修复】必须尊重 setLocalStorageSafely 的返回值：
                // 它内部自带 try/catch，localStorage 配额满 / 存储被禁用时
                // 返回 false 并弹错误提示，但**不会抛异常**。旧写法不看返回值、
                // 恒定返回 true，上层就会误报「预设已保存」——用户关掉面板再
                // 打开发现内容没了，其实数据从来没写进 localStorage。
                return setLocalStorageSafely(KEY, JSON.stringify(value), '提示词预设') !== false;
            }
            localStorage.setItem(KEY, JSON.stringify(value));
            return true;
        } catch (e) {
            toast('保存失败：浏览器存储可能已满', 'ri-error-warning-line');
            return false;
        }
    }

    /* ---------------- 数据层 ---------------- */

    var uidSeq = 0;
    function newId() { uidSeq += 1; return 'pp_' + Date.now().toString(36) + '_' + uidSeq; }

    function defaultPreset() {
        return {
            id: 'default',
            name: '默认预设（空白）',
            main: '',
            auxiliary: '',
            postHistory: '',
            enabled: true
        };
    }

    function normalizePreset(raw) {
        var p = raw && typeof raw === 'object' ? raw : {};
        return {
            id: String(p.id || '') || newId(),
            name: String(p.name || '未命名预设'),
            main: String(p.main || ''),
            auxiliary: String(p.auxiliary || ''),
            postHistory: String(p.postHistory || ''),
            enabled: p.enabled !== false
        };
    }

    function loadAll() {
        var data = readJson(KEY, null);
        if (!data || !Array.isArray(data.presets) || !data.presets.length) {
            return { version: 1, active: 'default', presets: [defaultPreset()] };
        }
        return {
            version: 1,
            active: String(data.active || ''),
            presets: data.presets.map(normalizePreset)
        };
    }

    function saveAll(data) { return saveJson(data); }

    function activePreset() {
        var data = loadAll();
        for (var i = 0; i < data.presets.length; i++) {
            if (data.presets[i].id === data.active) return data.presets[i];
        }
        return data.presets[0] || null;
    }

    /* ---------------- 轻量模板引擎 ---------------- */

    function renderTemplate(tpl, vars) {
        if (!tpl) return '';
        var out = String(tpl);
        var guard = 0;
        var re = /\{\{#if\s+([\w.]+)\}\}([\s\S]*?)\{\{\/if\}\}/;
        while (guard++ < 60) {
            var m = out.match(re);
            if (!m) break;
            var key = m[1];
            var body = m[2];
            var parts = body.split('{{else}}');
            var v = vars[key];
            var truthy = !!(v != null && String(v).trim());
            out = out.replace(m[0], truthy ? (parts[0] || '') : (parts[1] || ''));
        }
        out = out.replace(/\{\{([\w.]+)\}\}/g, function (all, k) {
            var v2 = vars[k];
            return v2 == null ? '' : String(v2);
        });
        return out;
    }

    /* ---------------- 注入逻辑（ChatHooks · promptAssembly 阶段） ---------------- */

    function buildVars(meta) {
        return {
            user: (meta && meta.user) || '',
            char: (meta && meta.char) || '',
            date: new Date().toLocaleDateString('zh-CN'),
            time: new Date().toLocaleTimeString('zh-CN')
        };
    }

    /**
     * 把当前预设的三段文本注入 messages（OpenAI 格式，原地修改）：
     *   main        → 拼到第一条 system 的前面（没有 system 就新建一条放最前）
     *   auxiliary   → 拼到第一条 system 的末尾
     *   postHistory → 拼到最后一条 user 消息末尾（没有则追加一条 user），
     *                 紧贴模型最后读到的位置，适合「只用中文回答」这类硬约束
     */
    function injectIntoMessages(messages, meta) {
        var preset = activePreset();
        if (!preset || !preset.enabled) return;
        if (!Array.isArray(messages) || !messages.length) return;
        if (!preset.main && !preset.auxiliary && !preset.postHistory) return;
        // 辅助视觉请求（表情包自动备注的图像描述小任务）不打预设：那不是角色对话，
        // 注入只会白耗额度。识别特征：仅 2 条消息 + 唯一 user 消息含 image_url +
        // system 提示是本站在 chat.js 里写死的「图像描述助手」。
        if (messages.length === 2
            && messages[0] && messages[0].role === 'system'
            && messages[1] && messages[1].role === 'user' && Array.isArray(messages[1].content)
            && messages[1].content.some(function (p) { return p && p.type === 'image_url'; })
            && /图像描述助手/.test(String(messages[0].content || ''))) return;
        var vars = buildVars(meta);
        var main = renderTemplate(preset.main, vars).replace(/\s+$/, '');
        var auxiliary = renderTemplate(preset.auxiliary, vars).replace(/\s+$/, '');
        var postHistory = renderTemplate(preset.postHistory, vars).replace(/\s+$/, '');
        if (!main && !auxiliary && !postHistory) return;

        var sysIdx = -1;
        for (var i = 0; i < messages.length; i++) {
            var m0 = messages[i];
            if (m0 && m0.role === 'system') { sysIdx = i; break; }
        }
        var prefix = main ? (main + '\n\n') : '';
        var suffix = auxiliary ? ('\n\n' + auxiliary) : '';

        if (sysIdx >= 0) {
            var sys = messages[sysIdx];
            if (typeof sys.content === 'string') {
                sys.content = prefix + sys.content + suffix;
            } else if (Array.isArray(sys.content)) {
                var firstText = -1;
                for (var j = 0; j < sys.content.length; j++) {
                    var part = sys.content[j];
                    if (part && part.type === 'text' && typeof part.text === 'string') { firstText = j; break; }
                }
                if (firstText >= 0) {
                    sys.content[firstText].text = prefix + sys.content[firstText].text + suffix;
                } else if (prefix || suffix) {
                    sys.content.unshift({ type: 'text', text: (prefix + suffix).replace(/^\n+|\n+$/g, '') });
                }
            }
        } else if (prefix || suffix) {
            messages.unshift({ role: 'system', content: (prefix + suffix).replace(/^\n+|\n+$/g, '') });
        }

        if (postHistory) {
            var last = messages[messages.length - 1];
            if (last && last.role === 'user' && typeof last.content === 'string') {
                last.content = last.content + '\n\n' + postHistory;
            } else {
                messages.push({ role: 'user', content: postHistory });
            }
        }
    }

    function connect() {
        if (!window.ChatHooks || typeof window.ChatHooks.register !== 'function') return false;
        window.ChatHooks.register('promptAssembly', 'prompt-presets', function (messages, meta) {
            try { injectIntoMessages(messages, meta); } catch (e) {}
        }, 60);
        return true;
    }

    if (!connect()) {
        var tries0 = 0;
        var timer0 = setInterval(function () {
            tries0 += 1;
            if (connect() || tries0 > 80) clearInterval(timer0);
        }, 250);
    }

    /* ---------------- 设置面板（设置 → 插件 → 提示词预设） ---------------- */

    var overlay = null;
    var editingId = '';
    // 编辑器「最近一次与数据同步」的快照：关闭 / 切换编辑对象 / 清空表单前，
    // 用它判断编辑框里有没有未保存的修改，防止用户填了半天内容被静默清掉。
    var editorSnapshot = '';

    function q(sel) { return overlay ? overlay.querySelector(sel) : null; }

    /* ---------------- 未保存修改保护 ----------------
       旧版对编辑框内容没有任何保护：关面板（✕ / 点遮罩 / Esc）、点列表里的
       「编辑」切换对象、点「清空表单」，都会直接把编辑框内容换掉或清空，
       且没有任何提示 —— 用户填完内容关掉再打开，看到的就是「内容都没了」。
       下面把这三条路径统一加上「有未保存修改先确认」。 */

    function editorState() {
        return JSON.stringify([
            q('#pp-name') ? q('#pp-name').value : '',
            q('#pp-main') ? q('#pp-main').value : '',
            q('#pp-aux') ? q('#pp-aux').value : '',
            q('#pp-post') ? q('#pp-post').value : '',
            q('#pp-enabled') ? (q('#pp-enabled').checked ? 1 : 0) : 1
        ]);
    }

    function captureSnapshot() { editorSnapshot = editorState(); }

    function isEditorDirty() {
        if (!overlay) return false;
        return editorState() !== editorSnapshot;
    }

    /** 有未保存修改时先确认，用户坚持才执行 action（丢弃修改） */
    function confirmDiscard(message, action) {
        if (!isEditorDirty()) { action(); return; }
        if (window.Dlg && window.Dlg.confirm) {
            window.Dlg.confirm({
                title: '有未保存的修改',
                message: message,
                okText: '放弃修改',
                cancelText: '继续编辑',
                danger: true
            }).then(function (yes) { if (yes) action(); });
        } else if (window.confirm(message)) {
            action();
        }
    }

    function injectStyle() {
        if (document.getElementById('pp-style')) return;
        var st = document.createElement('style');
        st.id = 'pp-style';
        st.textContent = [
            '.pp-tip{font-size:.82em;color:#8d93a1;line-height:1.7;margin:0 0 10px}',
            '.pp-row{display:flex;align-items:center;gap:8px;padding:9px 10px;border:1px solid #3b3f4b;border-radius:10px;margin-bottom:8px;background:rgba(255,255,255,.03)}',
            '.pp-row .pp-main{flex:1 1 auto;min-width:0}',
            '.pp-name{font-size:.9em;color:#e6c78a;word-break:break-all}',
            '.pp-meta{font-size:.74em;color:#8d93a1;margin-top:3px}',
            '.pp-editor{display:flex;flex-direction:column;gap:8px;padding:12px;border:1px solid #3b3f4b;border-radius:10px;background:rgba(255,255,255,.03);margin-bottom:14px}',
            '.pp-editor input[type=text],.pp-editor textarea{width:100%;box-sizing:border-box;padding:8px;background:#20232c;border:1px solid #4a4e5c;border-radius:7px;color:#eee;font:inherit;font-size:.85em}',
            '.pp-editor textarea{min-height:84px;resize:vertical;line-height:1.6}',
            '.pp-l{font-size:.8em;color:#9aa0ad;display:block;margin-bottom:4px}',
            '.pp-acts{display:flex;gap:8px;flex-wrap:wrap}',
            '.pp-en{display:flex;align-items:center;gap:6px;font-size:.85em;color:#cfd3dd}',
            '.pp-empty{color:#8d93a1;font-size:.85em;text-align:center;padding:16px 0}'
        ].join('');
        document.head.appendChild(st);
    }

    function refreshPanel() { renderList(); }

    /**
     * 兜底恢复：主读写位是 localStorage，setLocalStorageSafely 会同步写一份
     * IndexedDB 镜像。极少数情况下 localStorage 侧的数据会丢（配额满时保存
     * 失败、存储被外部清理等），镜像里可能还留着最近一次成功写入的内容 ——
     * 打开面板时若发现本地**没有任何有效预设**，异步比对镜像并恢复，
     * 尽量不让用户看到「预设都没了」。只在完全没有数据时触发，不会覆盖正常数据。
     */
    function tryRestoreFromIdbMirror() {
        if (typeof IndexedDBStorage === 'undefined' || typeof IndexedDBStorage.getRecord !== 'function') return;
        var current = readJson(KEY, null);
        if (current && Array.isArray(current.presets) && current.presets.length) return;
        IndexedDBStorage.getRecord(KEY).then(function (record) {
            if (!record || !record.value) return;
            var data = null;
            try { data = JSON.parse(record.value); } catch (e) { return; }
            if (!data || !Array.isArray(data.presets) || !data.presets.length) return;
            // 等待期间用户可能已手动保存：再查一次，有数据就不再回填
            var latest = readJson(KEY, null);
            if (latest && Array.isArray(latest.presets) && latest.presets.length) return;
            if (!saveJson(data)) return;
            if (overlay) { renderList(); toast('检测到本机数据异常，已从备份恢复预设', 'ri-history-line'); }
        }).catch(function () { /* 镜像不存在或读取失败：保持原状 */ });
    }

    function renderList() {
        var host = q('#pp-list');
        if (!host) return;
        var data = loadAll();
        var html = '';
        data.presets.forEach(function (p) {
            var flags = [];
            if (p.main) flags.push('主');
            if (p.auxiliary) flags.push('辅');
            if (p.postHistory) flags.push('后');
            html += '<div class="pp-row" data-id="' + esc(p.id) + '">' +
                '<input type="radio" name="pp-active" data-act="active"' + (p.id === data.active ? ' checked' : '') + ' title="设为当前使用的预设">' +
                '<div class="pp-main">' +
                '<div class="pp-name">' + esc(p.name) + (p.enabled ? '' : '（已停用）') + '</div>' +
                '<div class="pp-meta">' + (flags.join(' + ') || '空预设') + '</div>' +
                '</div>' +
                '<button class="btn btn-outline btn-sm" data-act="edit">编辑</button>' +
                '<button class="btn btn-outline btn-sm" data-act="copy">复制</button>' +
                '<button class="btn btn-danger btn-sm" data-act="del">删</button>' +
                '</div>';
        });
        host.innerHTML = html || '<p class="pp-empty">还没有预设，先在下面填写并保存即可创建。</p>';
    }

    function fillEditor(p) {
        editingId = p ? p.id : '';
        if (q('#pp-name')) q('#pp-name').value = p ? p.name : '';
        if (q('#pp-main')) q('#pp-main').value = p ? p.main : '';
        if (q('#pp-aux')) q('#pp-aux').value = p ? p.auxiliary : '';
        if (q('#pp-post')) q('#pp-post').value = p ? p.postHistory : '';
        if (q('#pp-enabled')) q('#pp-enabled').checked = p ? p.enabled !== false : true;
        if (q('#pp-save')) q('#pp-save').innerHTML = p ? '<i class="ri-save-line"></i> 保存修改' : '<i class="ri-add-line"></i> 新建预设';
        // 记录快照：此后编辑框里的任何改动都算「未保存修改」
        captureSnapshot();
    }

    function saveEditor() {
        var name = String(q('#pp-name') ? q('#pp-name').value : '').trim() || '未命名预设';
        var item = {
            id: editingId || ('pp_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7)),
            name: name,
            main: String(q('#pp-main') ? q('#pp-main').value : ''),
            auxiliary: String(q('#pp-aux') ? q('#pp-aux').value : ''),
            postHistory: String(q('#pp-post') ? q('#pp-post').value : ''),
            enabled: q('#pp-enabled') ? q('#pp-enabled').checked !== false : true
        };
        var data = loadAll();
        var idx = -1;
        for (var i = 0; i < data.presets.length; i++) { if (data.presets[i].id === editingId) { idx = i; break; } }
        if (idx >= 0) data.presets[idx] = item;
        else {
            data.presets.push(item);
            if (!data.active) data.active = item.id;
        }
        if (saveAll(data)) {
            editingId = item.id;
            fillEditor(item);
            renderList();
            toast('预设已保存：' + name, 'ri-check-line');
        }
    }

    function setActive(id) {
        var data = loadAll();
        data.active = id;
        if (saveAll(data)) {
            renderList();
            var p = activePreset();
            toast('当前预设：' + (p ? p.name : ''), 'ri-check-line');
        }
    }

    function copyPreset(id) {
        var data = loadAll();
        for (var i = 0; i < data.presets.length; i++) {
            if (data.presets[i].id === id) {
                var c = normalizePreset(JSON.parse(JSON.stringify(data.presets[i])));
                c.id = 'pp_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
                c.name = data.presets[i].name + ' 副本';
                data.presets.splice(i + 1, 0, c);
                break;
            }
        }
        if (saveAll(data)) { renderList(); toast('已复制', 'ri-file-copy-line'); }
    }

    function delPreset(id) {
        var data = loadAll();
        if (data.presets.length <= 1) { toast('至少保留一个预设', 'ri-error-warning-line'); return; }
        var go = function () {
            data.presets = data.presets.filter(function (p) { return p.id !== id; });
            if (data.active === id) data.active = data.presets[0].id;
            if (saveAll(data)) {
                if (editingId === id) fillEditor(null);
                renderList();
                toast('已删除', 'ri-delete-bin-line');
            }
        };
        if (window.Dlg && window.Dlg.confirm) window.Dlg.confirm({ title: '删除预设', message: '删除后不可恢复。', okText: '删除' }).then(function (yes) { if (yes) go(); });
        else if (window.confirm('删除该预设？')) go();
    }

    function exportAll() {
        var data = loadAll();
        try {
            var payload = { app: 'MySW', kind: 'promptPresets', version: 1, exportedAt: Date.now(), active: data.active, presets: data.presets };
            var blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
            var url = URL.createObjectURL(blob);
            var a = document.createElement('a');
            a.href = url;
            a.download = 'mysw-prompt-presets-' + Date.now() + '.json';
            document.body.appendChild(a);
            a.click();
            a.remove();
            setTimeout(function () { try { URL.revokeObjectURL(url); } catch (e) {} }, 4000);
            toast('预设已导出', 'ri-download-line');
        } catch (e) { toast('导出失败：' + e.message, 'ri-error-warning-line'); }
    }

    function importFile(file) {
        var reader = new FileReader();
        reader.onload = function () {
            try {
                var data = JSON.parse(String(reader.result || ''));
                // 第三方「单文件预设分享格式」会把酒馆预设包在 preset.data 里
                if (data && data.preset && data.preset.data && isSillyTavernPreset(data.preset.data)) data = data.preset.data;
                // 酒馆预设：直接转成一条本站预设
                if (isSillyTavernPreset(data)) {
                    var converted = fromSillyTavernPreset(data, (file.name || '').replace(/\.json$/i, ''));
                    if (!converted.main && !converted.postHistory && !converted.auxiliary) {
                        throw new Error('这个酒馆预设里没有可迁移的提示词内容（可能只包含了采样参数）');
                    }
                    var allST = loadAll();
                    converted.id = 'pp_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
                    allST.presets.push(normalizePreset(converted));
                    if (saveAll(allST)) {
                        renderList();
                        toast('已导入酒馆预设「' + converted.name + '」', 'ri-upload-line');
                    }
                    return;
                }
                var incoming = Array.isArray(data) ? data : (data && Array.isArray(data.presets) ? data.presets : []);
                if (!incoming.length) throw new Error('文件里没有预设数据');
                var all = loadAll();
                var added = 0;
                incoming.forEach(function (raw) {
                    var p = normalizePreset(raw);
                    p.id = 'pp_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
                    all.presets.push(p);
                    added += 1;
                });
                if (saveAll(all)) { renderList(); toast('已导入 ' + added + ' 套预设', 'ri-upload-line'); }
            } catch (e) { toast('导入失败：' + e.message, 'ri-error-warning-line'); }
        };
        reader.readAsText(file);
    }

    function onEsc(e) {
        if (e.key === 'Escape') { e.stopPropagation(); requestClosePanel(); }
    }

    /** 统一关闭入口（✕ / 点遮罩 / Esc）：有未保存修改先确认，避免内容被静默清掉 */
    function requestClosePanel() {
        if (!overlay) return;
        confirmDiscard('关闭后，编辑框里还没保存的内容会丢失。确定要关闭吗？', closePanel);
    }

    function closePanel() {
        if (!overlay) return;
        var el = overlay;
        overlay = null;
        el.classList.remove('show');
        setTimeout(function () { try { el.remove(); } catch (e) {} }, 180);
        document.removeEventListener('keydown', onEsc, true);
    }

    function openPanel() {
        injectStyle();
        // 兜底：overlay 的 DOM 若被外部逻辑清掉而模块变量还留着引用，面板会再也打不开；
        // 打开前先核对节点是否还在文档里，不在就丢弃旧引用重建。
        if (overlay && !document.body.contains(overlay)) overlay = null;
        if (overlay) return;
        overlay = document.createElement('div');
        overlay.className = 'modal-overlay show';
        overlay.style.zIndex = '3300';
        overlay.innerHTML =
            "<div class='modal-content vn-modal' style='max-width:760px'>" +
            "<div class='modal-header'><h2><i class='ri-book-2-line'></i> 提示词预设</h2>" +
            "<button type='button' class='close-modal' id='pp-close' aria-label='关闭'><i class='ri-close-line'></i></button></div>" +
            "<div class='modal-body'>" +
            "<p class='pp-tip'>预设是独立于角色卡的「全局提示词层」：主提示词拼在系统提示词最前面，辅助提示词拼在末尾，历史后指令放在对话历史之后（越靠近模型最后读到的位置，服从性越高）。不改动任何角色卡，随时可切换或停用。</p>" +
            "<div id='pp-list'></div>" +
            "<div class='pp-editor' id='pp-editor'>" +
            "<div><label class='pp-l'>预设名称</label><input type='text' id='pp-name' placeholder='例如：中文强制 / 简洁回复'></div>" +
            "<div><label class='pp-l'>主提示词（Main）</label><textarea id='pp-main' placeholder='例如：你必须在所有回复中保持角色设定，不得跳出。'></textarea></div>" +
            "<div><label class='pp-l'>辅助提示词（Auxiliary）</label><textarea id='pp-aux' placeholder='例如：回复长度控制在 200 字以内，多用动作与神态描写。'></textarea></div>" +
            "<div><label class='pp-l'>历史后指令（Post-History）</label><textarea id='pp-post' placeholder='例如：请始终使用简体中文回复。'></textarea></div>" +
            "<label class='pp-en'><input type='checkbox' id='pp-enabled' checked> 启用此预设</label>" +
            "<div class='pp-acts'>" +
            "<button class='btn btn-primary btn-sm' id='pp-save'><i class='ri-add-line'></i> 新建预设</button>" +
            "<button class='btn btn-outline btn-sm' id='pp-new'><i class='ri-eraser-line'></i> 清空表单</button>" +
            "<button class='btn btn-outline btn-sm' id='pp-export'><i class='ri-download-line'></i> 导出全部</button>" +
            "<button class='btn btn-outline btn-sm' id='pp-export-st'><i class='ri-file-download-line'></i> 导出酒馆预设</button>" +
            "<button class='btn btn-outline btn-sm' id='pp-import'><i class='ri-upload-line'></i> 导入 JSON</button>" +
            "<input type='file' id='pp-import-file' accept='.json,application/json' hidden>" +
            "</div>" +
            "<p class='pp-tip' style='margin:0'>可用变量：{{user}}（你的名字）、{{char}}（角色名）、{{date}}、{{time}}；条件块：{{#if user}}...{{else}}...{{/if}}（变量非空为真）。</p>" +
            "</div>" +
            "</div></div>";
        document.body.appendChild(overlay);
        overlay.addEventListener('click', function (e) { if (e.target === overlay) requestClosePanel(); });
        document.addEventListener('keydown', onEsc, true);
        q('#pp-close').addEventListener('click', requestClosePanel);
        q('#pp-save').addEventListener('click', saveEditor);
        q('#pp-new').addEventListener('click', function () {
            confirmDiscard('清空表单会丢弃编辑框里还没保存的内容。确定要清空吗？', function () { fillEditor(null); });
        });
        q('#pp-export').addEventListener('click', exportAll);
        q('#pp-export-st').addEventListener('click', exportAsSillyTavern);
        q('#pp-import').addEventListener('click', function () { var f = q('#pp-import-file'); if (f) f.click(); });
        q('#pp-import-file').addEventListener('change', function (e) {
            var f = e.target.files && e.target.files[0];
            if (f) importFile(f);
            e.target.value = '';
        });
        q('#pp-list').addEventListener('click', function (e) {
            var btn = e.target && e.target.closest ? e.target.closest('[data-act]') : null;
            if (!btn) return;
            var row = btn.closest('.pp-row');
            var id = row ? row.getAttribute('data-id') : '';
            if (!id) return;
            var act = btn.getAttribute('data-act');
            if (act === 'edit') {
                var data = loadAll();
                var target = null;
                for (var i = 0; i < data.presets.length; i++) { if (data.presets[i].id === id) { target = data.presets[i]; break; } }
                if (!target) return;
                // 切编辑对象会覆盖当前编辑框：有未保存内容时先确认，防止静默丢内容
                confirmDiscard('编辑框里有未保存的修改，切到「' + target.name + '」会覆盖这些内容。', function () { fillEditor(target); });
            } else if (act === 'copy') { copyPreset(id); }
            else if (act === 'del') { delPreset(id); }
        });
        q('#pp-list').addEventListener('change', function (e) {
            var el = e.target;
            if (!el || !el.getAttribute || el.getAttribute('data-act') !== 'active') return;
            var row = el.closest ? el.closest('.pp-row') : null;
            var id = row ? row.getAttribute('data-id') : '';
            if (id) setActive(id);
        });
        fillEditor(null);
        renderList();
        // 兜底：本地数据异常缺失时，尝试从 IndexedDB 镜像恢复（防「预设都没了」）
        tryRestoreFromIdbMirror();
    }

    function mountEntry() {
        var host = document.getElementById('tab-plugins');
        if (!host || host.querySelector('.pp-entry')) return !!host;
        var block = document.createElement('div');
        block.className = 'form-group pp-entry';
        block.style.cssText = 'border-top:1px dashed #444;padding-top:15px;margin-top:15px;';
        block.innerHTML =
            "<h3 style='margin-bottom:10px;color:#e6c78a;'><i class='ri-book-2-line'></i> 提示词预设（Preset）</h3>" +
            "<p style='font-size:.85em;color:#aaa;margin-bottom:12px;line-height:1.7'>不改角色卡，为每一轮请求叠加三段可编辑文本（主提示词 / 辅助提示词 / 历史后指令），支持 {{user}}、{{char}} 变量与 {{#if}} 条件块，可建多套预设一键切换。</p>" +
            "<button class='btn btn-outline btn-sm' id='pp-open-btn'><i class='ri-settings-4-line'></i> 管理预设</button>";
        host.appendChild(block);
        var btn = block.querySelector('#pp-open-btn');
        if (btn) btn.addEventListener('click', openPanel);
        return true;
    }

    function boot() {
        injectStyle();
        var tries = 0;
        (function attempt() {
            tries += 1;
            if (mountEntry()) return;
            if (tries < 40) setTimeout(attempt, 400);
        })();
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
    else boot();

    window.PromptPresets = {
        list: function () { return loadAll(); },
        active: activePreset,
        renderTemplate: renderTemplate,
        injectIntoMessages: injectIntoMessages,
        openPanel: openPanel,
        // 供「酒馆整包搬家」等模块批量导入酒馆预设
        importSillyTavernObjects: importSillyTavernObjects,
        fromSillyTavern: fromSillyTavernPreset,
        toSillyTavern: toSillyTavernPreset
    };
})();


/* ====== vn-live2d.js ====== */
/**
 * vn-live2d.js —— 视觉小说模式的 Live2D 立绘
 * 1) Cubism Core（官方 SDK 域名）
 * 2) pixi.js v6
 * 3) pixi-live2d-display（Cubism 4 适配）
 * 存储：localStorage['vnLive2D']
 * { enabled: true, models: { [friendId]: 'https://.../x.model3.json' } }
 */
(function () {
    'use strict';
    if (window.ScriptLoader && typeof ScriptLoader.isEnabled === 'function' && !ScriptLoader.isEnabled('vn-live2d.js')) return;

    var KEY = 'vnLive2D';
    var CORE_URL = 'https://cubism.live2d.com/sdk-web/cubismcore/live2dcubismcore.min.js';
    var PIXI_URL = 'https://cdn.jsdelivr.net/npm/pixi.js@6.5.10/dist/browser/pixi.min.js';
    var L2D_URL = 'https://cdn.jsdelivr.net/npm/pixi-live2d-display@0.4.0/dist/cubism4.min.js';

    var deps = null;
    var app = null;
    var model = null;
    var hostEl = null;
    var mountedUrl = '';
    var token = 0;
    var resizeObs = null;
    var scanTimer = 0;
    var failNoted = {};

    function toast(msg, icon) {
        try { if (typeof window.showToast === 'function') window.showToast(msg, icon || 'ri-information-line'); } catch (e) {}
    }

    function esc(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, function (ch) {
            var c = ch.charCodeAt(0);
            if (c === 38) return '&amp;';
            if (c === 60) return '&lt;';
            if (c === 62) return '&gt;';
            if (c === 34) return '&quot;';
            return '&#39;';
        });
    }

    function readAll() {
        try {
            var raw = localStorage.getItem(KEY);
            var d = raw ? JSON.parse(raw) : null;
            if (!d || typeof d !== 'object') d = {};
            if (!d.models || typeof d.models !== 'object') d.models = {};
            return { enabled: d.enabled !== false, models: d.models };
        } catch (e) { return { enabled: true, models: {} }; }
    }

    function writeAll(d) {
        try {
            if (typeof setLocalStorageSafely === 'function') return setLocalStorageSafely(KEY, JSON.stringify(d), 'VN Live2D') !== false;
            localStorage.setItem(KEY, JSON.stringify(d));
            return true;
        } catch (e) { toast('保存失败：浏览器存储不可用', 'ri-error-warning-line'); return false; }
    }

    function fid() {
        try { if (window.currentFriendId != null) return String(window.currentFriendId); } catch (e) {}
        var el = document.querySelector('.friend-item.active');
        if (el) {
            var a = el.getAttribute('data-friend-id') || el.getAttribute('data-id');
            if (a) return String(a);
        }
        return '';
    }

    function fname(id) {
        try {
            var data = window.friendsData;
            if (!data && typeof window.getFriends === 'function') data = window.getFriends();
            var fr = data && data[id];
            if (fr && fr.name) return String(fr.name);
        } catch (e) {}
        return id || '当前角色';
    }

    function loadScriptOnce(src) {
        return new Promise(function (resolve, reject) {
            var el = document.createElement('script');
            el.src = src;
            el.async = false;
            el.onload = function () { resolve(); };
            el.onerror = function () { reject(new Error('加载失败：' + src)); };
            document.head.appendChild(el);
        });
    }

    function ensureDeps() {
        if (deps) return deps;
        deps = loadScriptOnce(CORE_URL)
            .then(function () { return loadScriptOnce(PIXI_URL); })
            .then(function () { return loadScriptOnce(L2D_URL); })
            .then(function () {
                if (!window.PIXI || !window.PIXI.live2d || !window.PIXI.live2d.Live2DModel) {
                    throw new Error('pixi-live2d-display 未就绪');
                }
            })
            .catch(function (e) { deps = null; throw e; });
        return deps;
    }

    /* ---------------- 挂载与卸载 ---------------- */

    function stageVisible() {
        var el = document.getElementById('vn-stage');
        if (!el) return false;
        try {
            var cs = getComputedStyle(el);
            if (!cs || cs.display === 'none' || cs.visibility === 'hidden') return false;
            if (Number(cs.opacity) === 0) return false;
        } catch (e) { return false; }
        return true;
    }

    function showStaticImg(show) {
        var img = document.getElementById('vn-character');
        if (img) img.style.visibility = show ? '' : 'hidden';
    }

    function fit() {
        if (!model || !hostEl) return;
        var w = hostEl.clientWidth || 1;
        var h = hostEl.clientHeight || 1;
        var mw = model.width || 1;
        var mh = model.height || 1;
        var s = Math.min((w * 0.96) / mw, h / mh);
        try { model.scale.set(s); } catch (e) {}
        try { if (model.anchor && model.anchor.set) model.anchor.set(0.5, 1); } catch (e) {}
        try { model.x = w / 2; model.y = h; } catch (e) {}
    }

    function bindResize() {
        if (resizeObs || !hostEl) return;
        if (window.ResizeObserver) {
            resizeObs = new ResizeObserver(function () { fit(); });
            try { resizeObs.observe(hostEl); } catch (e) { resizeObs = null; }
        }
        if (!resizeObs) window.addEventListener('resize', fit);
    }

    function unmount() {
        token += 1;
        if (resizeObs) { try { resizeObs.disconnect(); } catch (e) {} resizeObs = null; }
        else { try { window.removeEventListener('resize', fit); } catch (e) {} }
        if (model) { try { model.destroy(); } catch (e) {} model = null; }
        if (app) { try { app.destroy(true, { children: true }); } catch (e) {} app = null; }
        if (hostEl) { try { hostEl.remove(); } catch (e) {} hostEl = null; }
        mountedUrl = '';
        showStaticImg(true);
    }

    function mount(url) {
        var wrap = document.getElementById('vn-char-wrap');
        if (!wrap) return;
        mountedUrl = url;
        var t = ++token;
        if (!hostEl) {
            try { if (getComputedStyle(wrap).position === 'static') wrap.style.position = 'relative'; } catch (e) {}
            hostEl = document.createElement('div');
            hostEl.className = 'vn-l2d-host';
            hostEl.style.cssText = 'position:absolute;left:0;top:0;right:0;bottom:0;pointer-events:none;z-index:2;';
            wrap.appendChild(hostEl);
        }
        ensureDeps().then(function () {
            if (t !== token || !hostEl) return;
            if (!app) {
                app = new PIXI.Application({
                    backgroundAlpha: 0, antialias: true, autoDensity: true,
                    resolution: Math.min(window.devicePixelRatio || 1, 2),
                    resizeTo: hostEl
                });
                app.view.style.width = '100%';
                app.view.style.height = '100%';
                app.view.style.display = 'block';
                hostEl.appendChild(app.view);
            }
            return PIXI.live2d.Live2DModel.from(url, { autoInteract: true }).then(function (m) {
                if (t !== token || !app) { try { m.destroy(); } catch (e) {} return; }
                model = m;
                app.stage.addChild(m);
                fit();
                setTimeout(fit, 300);
                bindResize();
                showStaticImg(false);
                syncCharVisibility();
            });
        }).catch(function (e) {
            if (!failNoted[url]) {
                failNoted[url] = true;
                toast('Live2D 加载失败，已回退静态立绘：' + (e && e.message ? e.message : e), 'ri-error-warning-line');
            }
            unmount();
        });
    }

    // 与静态立绘的显隐保持同步：VN 用 .hidden-char 类控制立绘（切到「我」发言、
    // 隐藏界面、该句没有立绘时都会加上）。Live2D 是独立的画布层，必须显式跟着
    // 隐藏，否则会出现「静态立绘没了、模型还挂在舞台上」的穿帮。
    function syncCharVisibility() {
        if (!hostEl) return;
        var img = document.getElementById('vn-character');
        var hidden = !!(img && img.classList.contains('hidden-char'));
        var next = hidden ? 'none' : '';
        if (hostEl.style.display !== next) hostEl.style.display = next;
    }

    function scan() {
        var st = readAll();
        if (!st.enabled) { if (mountedUrl || model) unmount(); return; }
        var url = String(st.models[fid()] || '').trim();
        if (!url) { if (mountedUrl || model) unmount(); return; }
        if (mountedUrl === url) { syncCharVisibility(); return; }
        if (!stageVisible()) return;
        unmount();
        mount(url);
    }

    function schedule(delay) {
        clearTimeout(scanTimer);
        scanTimer = setTimeout(function () { try { scan(); } catch (e) {} }, delay || 200);
    }

    /* ---------------- 启动扫描 ---------------- */

    function startWatching() {
        schedule(900);
        setInterval(function () { try { scan(); } catch (e) {} }, 2500);
        if (!window.MutationObserver || !document.body) return;
        var mo = new MutationObserver(function () { schedule(280); });
        try {
            mo.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'style'] });
        } catch (e) {}
    }

    startWatching();

    /* ---------------- 设置面板（设置 → 插件 → VN Live2D 立绘） ---------------- */

    var overlayEl = null;

    function q(sel) { return overlayEl ? overlayEl.querySelector(sel) : null; }

    function injectStyle() {
        if (document.getElementById('vnl2d-style')) return;
        var st = document.createElement('style');
        st.id = 'vnl2d-style';
        st.textContent = [
            '.vnl2d-tip{font-size:.82em;color:#8d93a1;line-height:1.7;margin:0 0 10px}',
            '.vnl2d-row{display:flex;align-items:center;gap:9px;padding:8px 10px;border:1px solid #3b3f4b;border-radius:10px;margin-bottom:8px;background:rgba(255,255,255,.03)}',
            '.vnl2d-row .m{flex:1 1 auto;min-width:0}',
            '.vnl2d-row .n{font-size:.9em;color:#e6c78a;word-break:break-all}',
            '.vnl2d-row .u{font-size:.72em;color:#8d93a1;word-break:break-all}',
            '.vnl2d-fields input{width:100%;box-sizing:border-box;padding:8px;background:#20232c;border:1px solid #4a4e5c;border-radius:7px;color:#eee;font:inherit;font-size:.85em}',
            '.vnl2d-btn{background:transparent;border:1px solid #4a4e5c;color:#cfd3dd;border-radius:8px;padding:5px 10px;font-size:.8em;cursor:pointer;white-space:nowrap}',
            '.vnl2d-btn:hover{border-color:#e6c78a;color:#e6c78a}',
            '.vnl2d-btn.danger:hover{border-color:#f06b78;color:#f06b78}'
        ].join('');
        document.head.appendChild(st);
    }

    function refreshList() {
        var host = q('#vnl2d-list');
        if (!host) return;
        var st = readAll();
        var keys = Object.keys(st.models).filter(function (k) { return String(st.models[k] || '').trim(); });
        if (!keys.length) {
            host.innerHTML = '<p style="color:#8d93a1;font-size:.85em;text-align:center;padding:14px 0">还没有为任何角色配置 Live2D 模型。</p>';
            return;
        }
        host.innerHTML = keys.map(function (k) {
            return '<div class="vnl2d-row">' +
                '<div class="m"><div class="n">' + esc(fname(k)) + '</div>' +
                '<div class="u">' + esc(st.models[k]) + '</div></div>' +
                '<button class="vnl2d-btn" data-k="' + esc(k) + '" data-a="use">填入</button>' +
                '<button class="vnl2d-btn danger" data-k="' + esc(k) + '" data-a="del">移除</button>' +
                '</div>';
        }).join('');
    }

    function onPanelEsc(e) { if (e.key === 'Escape') { e.stopPropagation(); closePanel(); } }

    function closePanel() {
        if (!overlayEl) return;
        var el = overlayEl;
        overlayEl = null;
        el.classList.remove('show');
        setTimeout(function () { try { el.remove(); } catch (e) {} }, 180);
        document.removeEventListener('keydown', onPanelEsc, true);
    }

    function openPanel() {
        injectStyle();
        if (overlayEl) return;
        var st = readAll();
        var curId = fid();
        overlayEl = document.createElement('div');
        overlayEl.className = 'modal-overlay show';
        overlayEl.style.zIndex = '3300';
        overlayEl.innerHTML =
            '<div class="modal-content vn-modal" style="max-width:640px">' +
            '<div class="modal-header"><h2><i class="ri-emotion-happy-line"></i> VN Live2D 立绘</h2>' +
            '<button type="button" class="close-modal" id="vnl2d-close" aria-label="关闭"><i class="ri-close-line"></i></button></div>' +
            '<div class="modal-body">' +
            '<p class="vnl2d-tip">为视觉小说模式的角色配置 Live2D 模型（.model3.json 的 HTTPS 直链，Cubism 3/4，需允许跨域）。' +
            '进入 VN 后模型会渲染在舞台上并播放自带的呼吸 / 眨眼 / 待机动作；未配置或加载失败时自动回退静态立绘。' +
            '运行库首次使用时从 CDN 加载（Cubism Core + pixi.js + pixi-live2d-display）。</p>' +
            '<label style="display:flex;align-items:center;gap:7px;font-size:.88em;color:#cfd3dd;margin-bottom:12px">' +
            '<input type="checkbox" id="vnl2d-enabled"' + (st.enabled ? ' checked' : '') + '> 启用 VN Live2D 立绘</label>' +
            '<div class="vnl2d-fields">' +
            '<label style="font-size:.8em;color:#9aa0ad">为「' + esc(fname(curId)) + '」配置模型地址</label>' +
            '<input type="url" id="vnl2d-url" placeholder="https://…/hiyori.model3.json" value="' + esc(st.models[curId] || '') + '">' +
            '</div>' +
            '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px">' +
            '<button class="vnl2d-btn" id="vnl2d-save">保存该角色模型</button>' +
            '<button class="vnl2d-btn danger" id="vnl2d-clear">清除该角色模型</button>' +
            '<button class="vnl2d-btn" id="vnl2d-refresh">立即刷新挂载</button>' +
            '</div>' +
            '<h4 style="margin:16px 0 8px;color:#e6c78a;font-size:.95em">已配置的角色</h4>' +
            '<div id="vnl2d-list"></div>' +
            '</div></div>';
        document.body.appendChild(overlayEl);
        overlayEl.addEventListener('click', function (e) { if (e.target === overlayEl) closePanel(); });
        document.addEventListener('keydown', onPanelEsc, true);
        q('#vnl2d-close').addEventListener('click', closePanel);
        q('#vnl2d-enabled').addEventListener('change', function () {
            var d = readAll();
            d.enabled = q('#vnl2d-enabled').checked;
            writeAll(d);
            schedule(120);
        });
        q('#vnl2d-save').addEventListener('click', function () {
            var url = String(q('#vnl2d-url').value || '').trim();
            var d = readAll();
            var id = fid();
            if (!url) delete d.models[id];
            else d.models[id] = url;
            if (writeAll(d)) { toast('已保存', 'ri-check-line'); refreshList(); schedule(120); }
        });
        q('#vnl2d-clear').addEventListener('click', function () {
            var d = readAll();
            delete d.models[fid()];
            if (writeAll(d)) {
                toast('已清除该角色的模型', 'ri-delete-bin-line');
                if (q('#vnl2d-url')) q('#vnl2d-url').value = '';
                refreshList();
                schedule(120);
            }
        });
        q('#vnl2d-refresh').addEventListener('click', function () { schedule(60); toast('已重新检查挂载状态', 'ri-refresh-line'); });
        q('#vnl2d-list').addEventListener('click', function (e) {
            var btn = e.target && e.target.closest ? e.target.closest('[data-k]') : null;
            if (!btn) return;
            var k = btn.getAttribute('data-k');
            if (btn.getAttribute('data-a') === 'del') {
                var d = readAll();
                delete d.models[k];
                if (writeAll(d)) { refreshList(); schedule(120); toast('已移除', 'ri-delete-bin-line'); }
            } else {
                var d2 = readAll();
                if (q('#vnl2d-url')) q('#vnl2d-url').value = d2.models[k] || '';
                toast('地址已填入输入框；切换到对应角色后打开本面板保存即可', 'ri-information-line');
            }
        });
        refreshList();
    }

    function mountEntry() {
        var host = document.getElementById('tab-plugins');
        if (!host) return false;
        if (host.querySelector('.vnl2d-entry')) return true;
        var block = document.createElement('div');
        block.className = 'form-group vnl2d-entry';
        block.style.cssText = 'border-top:1px dashed #444;padding-top:15px;margin-top:15px;';
        block.innerHTML =
            '<h3 style="margin-bottom:10px;color:#e6c78a;"><i class="ri-emotion-happy-line"></i> VN Live2D 立绘</h3>' +
            '<p style="font-size:.85em;color:#aaa;margin-bottom:12px;line-height:1.7">给视觉小说模式加上 Live2D：为角色配置 .model3.json 直链，进入 VN 后舞台显示可动立绘（自带呼吸 / 眨眼 / 待机动作），失败自动回退静态立绘。</p>' +
            '<button class="vnl2d-btn" id="vnl2d-open-btn"><i class="ri-settings-4-line"></i> 配置 Live2D 模型</button>';
        host.appendChild(block);
        var btn = block.querySelector('#vnl2d-open-btn');
        if (btn) btn.addEventListener('click', openPanel);
        return true;
    }

    function bootPanel() {
        injectStyle();
        var tries = 0;
        (function attempt() {
            tries += 1;
            if (mountEntry()) return;
            if (tries < 40) setTimeout(attempt, 400);
        })();
    }

    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bootPanel);
    else bootPanel();

    window.VNLive2D = {
        refresh: function () { schedule(60); },
        unmount: unmount,
        openPanel: openPanel,
        getConfig: readAll
    };
})();


