    var SPEED = [{ms:0,chunk:999},{ms:34,chunk:1},{ms:20,chunk:2},{ms:9,chunk:3}];

    var cfg = {speed:DATA.theme.speed||2, fontSize:DATA.theme.fontSize||16, autoDelay:1600, kenBurns:true, badge:true, md:true};
    var api = Object.assign({apiUrl:'',apiKey:'',model:'',temperature:0.8,maxTokens:1024,contextRounds:0,systemPrompt:DATA.systemPrompt||''}, DATA.api||{});
    var BT = String.fromCharCode(96);   // 反引号：整个运行时在外层 String.raw 模板里，不能直接写
